window.CHAPTER4_DATA = {"sections":[{"id":"c04-w01","number":1,"title":"휴가","formIds":["서식3"],"faqCategories":["휴가"],"contentBlocks":[{"id":"c04-w01-b1","title":"업무 흐름도","body":"휴가신청 ⇒ 휴가허가 ⇒ 휴가승인"},{"id":"c04-w01-b2","title":"세부내용 1. 휴가 개요","body":""},{"id":"c04-w01-b3","title":"관련법규 및 참고자료","body":"• 「지방공무원 복무규정」 제6조 및 제7조의8, 「지방공무원 복무에 관한 예규」"},{"id":"c04-w01-b4","title":"1. 휴가의 종류: 연가, 병가, 공가, 특별휴가","body":""},{"id":"c04-w01-b5","title":"2. 휴가 신청 및 허가 시기: 휴가 사유 발생 전까지","body":"▸불가피한 경우 다른 공무원이 대행"},{"id":"c04-w01-b6","title":"3. 휴가 일수의 계산","body":"▸휴가기간 중의 토요일 또는 공휴일은 그 휴가일수에 산입하지 아니함. 다만, 연가를 제외한 휴가기간이 30일 이상 계속되는 경우에는 그 휴가일수에 토요일 또는 공휴일 산입\n▸경조사 휴가는 그 사유가 발생한 날을 포함하여 전후에 연속하여 실시\n▸법정 휴가 일수를 초과한 휴가는 결근 처리"},{"id":"c04-w01-b7","title":"세부내용 2. 연가","body":""},{"id":"c04-w01-b8","title":"관련법규 및 참고자료","body":"• 「지방공무원 복무규정」 제7조~제7조의4, 「지방공무원 복무에 관한 예규」"},{"id":"c04-w01-b9","title":"1. 연가일수","body":"▸재직기간: 공무원연금법 제25조 적용\n재직기간 연가일수 재직기간 연가일수\n1개월 이상 ~ 1년 미만 1년 이상 ~ 3년 미만 3년 이상 ~ 4년 미만 11일 15일 16일 4년 이상 ~ 5년 미만 5년 이상 ~ 6년 미만 6년 이상 17일 20일 21일","tables":[{"headers":[{"text":"재직기간","colSpan":1,"rowSpan":1,"column":0},{"text":"연가일수","colSpan":1,"rowSpan":1,"column":1},{"text":"재직기간","colSpan":1,"rowSpan":1,"column":2},{"text":"연가일수","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"1개월 이상 ~ 1년 미만\n1년 이상 ~ 3년 미만\n3년 이상 ~ 4년 미만","colSpan":1,"rowSpan":1,"column":0},{"text":"11일\n15일\n16일","colSpan":1,"rowSpan":1,"column":1},{"text":"4년 이상 ~ 5년 미만\n5년 이상 ~ 6년 미만\n6년 이상","colSpan":1,"rowSpan":1,"column":2},{"text":"17일\n20일\n21일","colSpan":1,"rowSpan":1,"column":3}]],"widths":[30.1,19.57,30.76,19.57],"lineStart":1,"lineCount":2}]},{"id":"c04-w01-b10","title":"2. 연가일수의 가산: 총 2일까지 가산","body":"▸해당연도 연가보상비를 지급받지 못한 경우(미사용 연가 1일 이상): 다음해 1일 가산\n- 연가보상을 하지 않기로 한 권장연가일수 범위 내 미사용 연가일수는 가산대상 아님\n- 연가보상을 받고 남은 연가 모두 저축 시, 미보상 연가일수는 없으므로 가산사유 아님\n▸해당연도 병가 미사용에 따른 연가가산: 다음해 1일 가산\n- 반일병가･병지각･병조퇴･병외출의 누계가 8시간 미만인 경우에도 연가가산 대상이 아님"},{"id":"c04-w01-b11","title":"3. 연가일수의 공제","body":"▸결근, 정직, 직위해제, 강등처분에 따라 직무에 종사하지 못하는 일수는 연가일수에서 공제\n▸‘사실상 직무에 종사하지 않은 기간’이 있는 경우 해당 기간을 제외하고 다음 산식으로 일수 부여\n해당연도 중 사실상 직무에 종사한 기간(개월) 12개월 x 해당 연도 연가일수\n※ 15일 이상은 1월로 계산하고 15일 미만은 산입하지 않으며 소수점 이하의 일수는 반올림\n※ 사실상 직무에 종사하지 않은 기간: 휴직기간(공무상 질병 휴직 제외), 연도 중 신규임용 전 또는 퇴직 후 기간, 1개월 이상의 교육훈련 기간, 15일 이상 병가 기간 등\n▸연간 6일을 초과하는 병가 일수는 연가에서 공제(진단서가 첨부된 병가는 제외)","tables":[{"headers":[{"text":"해당연도 중 사실상 직무에 종사한 기간(개월)\n12개월","colSpan":1,"rowSpan":1,"column":0},{"text":"x 해당 연도 연가일수","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"※ 15일 이상은 1월로 계산하고 15일 미만은 산입하지 않으며 소수점 이하의 일수는 반올림","colSpan":2,"rowSpan":1,"column":0}]],"widths":[54.29,45.71],"lineStart":2,"lineCount":2}]},{"id":"c04-w01-b12","title":"4. 연가 당겨쓰기","body":"▸연가일수가 없는 경우 또는 당해 재직기간의 잔여 연가일수를 초과하는 사유 발생시 활용\n재직기간 연가일수 재직기간 연가일수\n1년 미만 1년 이상 ~ 2년 미만 2년 이상 ~ 3년 미만 5일 6일 7일 3년 이상 ~ 4년 미만 4년 이상 8일 10일","tables":[{"headers":[{"text":"재직기간","colSpan":1,"rowSpan":1,"column":0},{"text":"연가일수","colSpan":1,"rowSpan":1,"column":1},{"text":"재직기간","colSpan":1,"rowSpan":1,"column":2},{"text":"연가일수","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"1년 미만\n1년 이상 ~ 2년 미만\n2년 이상 ~ 3년 미만","colSpan":1,"rowSpan":1,"column":0},{"text":"5일\n6일\n7일","colSpan":1,"rowSpan":1,"column":1},{"text":"3년 이상 ~ 4년 미만\n4년 이상","colSpan":1,"rowSpan":1,"column":2},{"text":"8일\n10일","colSpan":1,"rowSpan":1,"column":3}]],"widths":[30.63,19.37,30.63,19.37],"lineStart":1,"lineCount":2}]},{"id":"c04-w01-b13","title":"5. 연가의 저축","body":"▸연가보상비 지급대상인 연가일수 중 미사용 연가일수를 이월 ･ 저축\n▸연가보상비 지급대상인 연가일수는「지방공무원 복무규정」에 따라 20일을 초과할 수 없으며, 연가사용 촉진을 위해 결정한 미보상 권장연가 일수는 이월 ･ 저축 불가\n※ 예시) 부여받은 연가 23일, 미보상 권장연가 10일, 연가보상 10일이고 사용 연가가 4일인 경우, 23일 중 권장연가 10일을 제외한 13일 내에서 이월 ･ 저축이 가능\n부여받은 연가일수: 23일\n연가저축 권장연가(미보상): 10일 연가 저축+보상 가능: 13일\n연가보상 연가 사용 4일 소멸 6일 저축 / 보상 10일 연가저축 가능 3일\n내년도 연가 가산 가능 연가 사용 4일 소멸 6일 저축 / 보상 10일 연가저축 2일 미사용 1일\n불가 연가 사용 4일 소멸 6일 저축 / 보상 10일 연가저축 가능 3일\n▸연가보상비 지급대상인 잔여연가 중 8시간 미만의 잔여연가는 자동으로 이월 ･ 저축 처리","tables":[{"headers":[{"text":"부여받은 연가일수: 23일","colSpan":7,"rowSpan":1,"column":0}],"rows":[[{"text":"연가저축","colSpan":2,"rowSpan":1,"column":0},{"text":"권장연가(미보상): 10일","colSpan":2,"rowSpan":1,"column":2},{"text":"연가 저축+보상 가능: 13일","colSpan":3,"rowSpan":1,"column":4}],[{"text":"연가보상","colSpan":2,"rowSpan":1,"column":0},{"text":"연가 사용 4일","colSpan":1,"rowSpan":1,"column":2},{"text":"소멸 6일","colSpan":1,"rowSpan":1,"column":3},{"text":"저축 / 보상 10일","colSpan":1,"rowSpan":1,"column":4},{"text":"연가저축 가능 3일","colSpan":2,"rowSpan":1,"column":5}],[{"text":"내년도\n연가 가산","colSpan":1,"rowSpan":2,"column":0},{"text":"가능","colSpan":1,"rowSpan":1,"column":1},{"text":"연가 사용 4일","colSpan":1,"rowSpan":1,"column":2},{"text":"소멸 6일","colSpan":1,"rowSpan":1,"column":3},{"text":"저축 / 보상 10일","colSpan":1,"rowSpan":1,"column":4},{"text":"연가저축 2일","colSpan":1,"rowSpan":1,"column":5},{"text":"미사용 1일","colSpan":1,"rowSpan":1,"column":6}],[{"text":"불가","colSpan":1,"rowSpan":1,"column":1},{"text":"연가 사용 4일","colSpan":1,"rowSpan":1,"column":2},{"text":"소멸 6일","colSpan":1,"rowSpan":1,"column":3},{"text":"저축 / 보상 10일","colSpan":1,"rowSpan":1,"column":4},{"text":"연가저축 가능 3일","colSpan":2,"rowSpan":1,"column":5}]],"widths":[9.72,7.75,18.17,14.24,19.5,16.84,13.78],"lineStart":3,"lineCount":5}]},{"id":"c04-w01-b14","title":"6. 연가사용의 권장","body":"▸자유롭고 계획적인 연가 사용으로 일과 휴식이 조화되는 직장문화 조성을 위하여 연가사용 권장제 운영\n▸매년 3월 31일까지 10일 이상의 권장연가 일수와 미사용 권장연가 일수 보상여부 결정\n▸미보상 권장연가 일수를 제외한 미사용 연가는 연가보상(보상범위 내) 또는 연가저축 활용\n▸눈치보지 않고 연가를 사용할 수 있는 자율적인 근무환경 조성으로 연가사용 활성화\n– 연가사유 묻지 않기(연가 신청 시 사유 미기재 등), 월별 1인 1일 이상 연가 신청하기 등\n▸사실상 직무에 종사하지 않은 기간이 있는 경우, 해당 기간을 제외하고 다음 산식으로 일수 지정\n해당연도 중 사실상 직무에 종사한 기간(개월) 12개월 x 권장 연가일수\n※ 15일 이상은 1월로 계산하고 15일 미만은 산입하지 않으며 소수점 이하는 일수는 반올림","tables":[{"headers":[{"text":"해당연도 중 사실상 직무에 종사한 기간(개월)\n12개월","colSpan":1,"rowSpan":1,"column":0},{"text":"x 권장 연가일수","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"※ 15일 이상은 1월로 계산하고 15일 미만은 산입하지 않으며 소수점 이하는 일수는 반올림","colSpan":2,"rowSpan":1,"column":0}]],"widths":[54.28,45.72],"lineStart":6,"lineCount":2}]},{"id":"c04-w01-b15","title":"세부내용 3. 병가","body":""},{"id":"c04-w01-b16","title":"관련법규 및 참고자료","body":"• 「지방공무원 복무규정」 제7조의5(병가)"},{"id":"c04-w01-b17","title":"1. 병가 일수","body":"▸일반병가: 연 60일 이내\n▸공무상 질병 또는 부상: 연 180일 이내\n▸병가일수는 1월 1일부터 12월 말까지 1년 단위로 계산\n▸질병 또는 부상으로 인한 지참, 조퇴, 외출은 누계 8시간을 병가 1일로 계산"},{"id":"c04-w01-b18","title":"2. 병가 사유","body":"▸질병 또는 부상으로 인하여 직무를 수행할 수 없을 때\n▸감염병에 걸려 그 공무원의 출근이 다른 공무원의 건강에 영향을 미칠 우려가 있을 때"},{"id":"c04-w01-b19","title":"3. 병가 운영 방법","body":"▸7일 이상 연속되거나 연간 누계가 6일을 초과하게 되는 경우 ｢의료법｣ 제17조 진단서 제출(매 사용 시). 단, 동일 사유의 병가는 최초 진단서로 갈음할 수 있음\n▸일반병가와 공무상 병가 일수는 각각 별도 운영\n▸공무상 질병 ･ 부상 사실여부 및 병가기간은 공무원재해보상법의 요양승인 결정 범위 내에서 기관장이 진단서와 해당 공무원의 직무수행 가능 여부 등을 감안하여 결정\n- 공무상요양승인을 신청하여 심의 중인 경우 일반병가와 연가 사용, 이후 공무상 질병 또는 부상으로 결정된 때에는 공무상 병가로 소급 처리할 수 있음\n- 공무상 질병·부상이 6일 이내의 단순 안정만을 요하는 경미한 경우 허가권자가 승인 가능"},{"id":"c04-w01-b20","title":"세부내용 4. 공가","body":""},{"id":"c04-w01-b21","title":"관련법규 및 참고자료","body":"• 「지방공무원 복무규정」 제7조의6, 「지방공무원 복무에 관한 예규」"},{"id":"c04-w01-b22","title":"1. 공가일수: 직접적으로 필요한 기간 또는 시간","body":""},{"id":"c04-w01-b23","title":"2. 공가 사유","body":"공가 사유\n｢병역법｣ 또는 그 밖의 다른 법령에 따른 병역판정검사·소집·검열점호 등에 응하거나 동원 또는 훈련에 참가할 때 공무에 관하여 국회, 법원, 검찰, 경찰, 그 밖의 기관에 소환될 때 법률에 따라 투표에 참가할 때, 승진시험·전직시험에 응시할 때 ｢산업안전보건법｣ 제129조부터 제131조까지의 규정에 따른 건강진단, ｢국민건강보험법｣ 제52조에 따른 건강검진 또는 ｢결핵예방법｣ 제11조 제1항에 따른 결핵검진 등을 받을 때, ｢혈액관리법｣에 따른 헌혈에 참가할 때 ｢지방공무원 교육훈련법 시행령｣ 제31조에 따른 외국어 능력시험에 응시할 때 천재지변, 교통차단 또는 그 밖의 사유로 출근이 불가능할 때 올림픽ㆍ전국체전 등 국가 또는 지방 단위의 주요 행사에 참가할 때 ｢공무원의 노동조합 설립 및 운영 등에 관한 법률｣ 제9조에 따른 교섭위원으로 선임되어 단체교섭 및 단체협약의 체결에 참석하거나 같은 법 제17조 및 ｢노동조합 및 노동관계조정법｣ 제17조에 따른 대의원회(｢공무원의 노동조합 설립 및 운영 등에 관한 법률｣에 따라 설립된 공무원 노동조합의 대의원회를 말하며, 연 1회로 한정한다)에 참석할 때 ｢검역법｣ 제5조제1항에 따른 검역관리지역 또는 중점검역관리지역으로 공무국외출장, 파견 또는 교육훈련을 가기 위해 같은 법에 따른 검역감염병의 예방접종을 할 때 원격지(遠隔地)로 전보 발령을 받고 부임할 때 「감염병의 예방 및 관리에 관한 법률」에 따른 제1급감염병에 대하여 같은 법 제24조 또는 제25조에 따라 필수예방접종 또는 임시예방접종을 받거나 같은 법 제42조제2항제3호에 따라 감염 여부 검사를 받을 때","tables":[{"headers":[{"text":"공가 사유","colSpan":1,"rowSpan":1,"column":0}],"rows":[[{"text":"｢병역법｣ 또는 그 밖의 다른 법령에 따른 병역판정검사·소집·검열점호 등에 응하거나 동원 또는 훈련에 참가할 때\n공무에 관하여 국회, 법원, 검찰, 경찰, 그 밖의 기관에 소환될 때\n법률에 따라 투표에 참가할 때, 승진시험·전직시험에 응시할 때\n｢산업안전보건법｣ 제129조부터 제131조까지의 규정에 따른 건강진단, ｢국민건강보험법｣ 제52조에 따른 건강검진 또는 ｢결핵예방법｣ 제11조 제1항에 따른 결핵검진 등을 받을 때, ｢혈액관리법｣에 따른 헌혈에 참가할 때\n｢지방공무원 교육훈련법 시행령｣ 제31조에 따른 외국어 능력시험에 응시할 때\n천재지변, 교통차단 또는 그 밖의 사유로 출근이 불가능할 때\n올림픽ㆍ전국체전 등 국가 또는 지방 단위의 주요 행사에 참가할 때\n｢공무원의 노동조합 설립 및 운영 등에 관한 법률｣ 제9조에 따른 교섭위원으로 선임되어 단체교섭 및 단체협약의 체결에 참석하거나 같은 법 제17조 및 ｢노동조합 및 노동관계조정법｣ 제17조에 따른 대의원회(｢공무원의 노동조합 설립 및 운영 등에 관한 법률｣에 따라 설립된 공무원 노동조합의 대의원회를 말하며, 연 1회로 한정한다)에 참석할 때\n｢검역법｣ 제5조제1항에 따른 검역관리지역 또는 중점검역관리지역으로 공무국외출장, 파견 또는 교육훈련을 가기 위해 같은 법에 따른 검역감염병의 예방접종을 할 때\n원격지(遠隔地)로 전보 발령을 받고 부임할 때\n「감염병의 예방 및 관리에 관한 법률」에 따른 제1급감염병에 대하여 같은 법 제24조 또는 제25조에 따라 필수예방접종 또는 임시예방접종을 받거나 같은 법 제42조제2항제3호에 따라 감염 여부 검사를 받을 때","colSpan":1,"rowSpan":1,"column":0}]],"widths":[100],"lineStart":0,"lineCount":2}]},{"id":"c04-w01-b24","title":"세부내용 5. 특별휴가","body":""},{"id":"c04-w01-b25","title":"관련법규 및 참고자료","body":"• 「지방공무원 복무규정」 제7조의7, 「지방공무원 복무에 관한 예규」\n• 「전북특별자치도교육감소속 지방공무원 복무 조례」제16조"},{"id":"c04-w01-b26","title":"1. 경조사 휴가","body":"▸경조사별 휴가일수\n구분 대상 일수\n결 혼 본인 5일\n자녀 1일\n본인 및 배우자의 형제자매 1일\n출 산 배우자(한 번에 둘 이상의 자녀를 출산한 경우) 20일(25일)\n입 양 본인 20일\n사 망 배우자, 본인 및 배우자의 부모 5일\n본인 및 배우자의 조부모ㆍ외조부모 3일\n자녀와 그 자녀의 배우자 3일\n본인 및 배우자의 형제 자매 3일\n본인 및 배우자의 형제 자매의 배우자 1일\n본인 및 배우자의 형제 자매와 그 형제 자매의 배우자 1일\n- 경조사 휴가는 그 사유가 발생한 날을 포함하여 전후에 연속하여 실시하는 것이 원칙\n- 본인 결혼은 그 사유가 발생한 날부터 30일 이내의 범위에서 사용 가능\n- 배우자 출산휴가의 경우에는 그 사유 발생일로부터 120일 이내의 범위에서 3회에 한하여 분할 사용 가능, 한 번에 둘 이상의 자녀를 출산한 경우에는 그 사유 발생일로부터 150일 이내의 범위에서 5회에 한하여 분할 사용 가능\n- 사망으로 인한 경조사 휴가의 경우 그 사유가 발생한 날 또는 사망일 다음날부터 휴가 사용 가능","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"대상","colSpan":1,"rowSpan":1,"column":1},{"text":"일수","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"결 혼","colSpan":1,"rowSpan":3,"column":0},{"text":"본인","colSpan":1,"rowSpan":1,"column":1},{"text":"5일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"자녀","colSpan":1,"rowSpan":1,"column":1},{"text":"1일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"본인 및 배우자의 형제자매","colSpan":1,"rowSpan":1,"column":1},{"text":"1일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"출 산","colSpan":1,"rowSpan":1,"column":0},{"text":"배우자(한 번에 둘 이상의 자녀를 출산한 경우)","colSpan":1,"rowSpan":1,"column":1},{"text":"20일(25일)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"입 양","colSpan":1,"rowSpan":1,"column":0},{"text":"본인","colSpan":1,"rowSpan":1,"column":1},{"text":"20일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"사 망","colSpan":1,"rowSpan":6,"column":0},{"text":"배우자, 본인 및 배우자의 부모","colSpan":1,"rowSpan":1,"column":1},{"text":"5일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"본인 및 배우자의 조부모ㆍ외조부모","colSpan":1,"rowSpan":1,"column":1},{"text":"3일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"자녀와 그 자녀의 배우자","colSpan":1,"rowSpan":1,"column":1},{"text":"3일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"본인 및 배우자의 형제 자매","colSpan":1,"rowSpan":1,"column":1},{"text":"3일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"본인 및 배우자의 형제 자매의 배우자","colSpan":1,"rowSpan":1,"column":1},{"text":"1일","colSpan":1,"rowSpan":1,"column":2}],[{"text":"본인 및 배우자의 형제 자매와 그 형제 자매의 배우자","colSpan":1,"rowSpan":1,"column":1},{"text":"1일","colSpan":1,"rowSpan":1,"column":2}]],"widths":[19.67,61.32,19.01],"lineStart":1,"lineCount":12}]},{"id":"c04-w01-b27","title":"2. 출산휴가 등","body":"▸임신 중인 공무원에 대해 출산 전후 90일(한 번에 둘 이상의 자녀를 임신한 경우 120일)의 출산휴가 허가(미숙아 100일)\n▸출산일 또는 출산예정일을 기준으로 출산 후 45일(한 번에 둘 이상의 자녀를 임신한 경우 60일) 이상 확보\n※ 단, 아래 사유로 출산휴가를 신청하는 경우에는 출산 전 어느 때라도 최장 44일\n(한 번에 둘 이상의 자녀를 임신한 경우에는 59일)의 범위에서 출산휴가를 나누어 사용할 수 있도록 함"},{"id":"c04-w01-b28","title":"1. 임신 중인 공무원이 유산(모자보건법 제14조제1항에 따라 허용되는 경우 외의 인공임신 중절에 의한 유산은 제외한다. 이하 제3호를 제외하고 같다)·사산의 경험이 있는 경우","body":""},{"id":"c04-w01-b29","title":"2. 임신 중인 공무원이 출산휴가를 신청할 당시 연령이 만 40세 이상인 경우","body":""},{"id":"c04-w01-b30","title":"3. 임신 중인 공무원이 조산·유산·사산의 위험이 있다는 의료기관의 진단서를 제출한 경우","body":"▸유산, 사산휴가(유산 또는 사산한 날부터, 30일 이상인 경우 토요일 또는 공휴일 포함)\n- 임신기간 15주 이내: 10일\n- 임신기간 16주 이상 ~ 21주 이내: 30일\n- 임신기간 22주 이상 ~ 27주 이내: 60일\n- 임신기간 28주 이상: 90일\n▸난임치료 시술휴가: 인공수정 2일(시술 당일 1일 포함), 체외수정 3~4일\n▸미숙아를 출산하여 1일 이내 신생아 중환자실에 입원한 경우 100일의 출산휴가 사용 가능"},{"id":"c04-w01-b31","title":"3. 여성보건 휴가","body":"▸여성공무원이 생리기간 중 휴식을 위해 매월 1일 사용(무급)"},{"id":"c04-w01-b32","title":"4. 임신검진휴가","body":"▸여성공무원이 임신기간 중 검진을 위해 10일 범위 내에서 사용(임신검진 확인자료 증빙 필요)"},{"id":"c04-w01-b33","title":"5. 모성보호시간","body":"▸임신 중인 여성공무원은 1일 2시간의 범위에서 휴식이나 병원진료를 위한 모성보호시간을 사용할 수 있음(근무시간 전·후 시간외 근무 불가)\n▸근무시간 중의 적절한 시간을 선택하여 신청\n- 병원에서 발급한 증빙서류로 확인(최초 이용 시에 한하여 제출)\n- 늦게 출근하거나, 일찍 퇴근 또는 근무시간 중 모두 활용 가능"},{"id":"c04-w01-b34","title":"6. 육아시간","body":"▸8세 이하 또는 초등학교 2학년 이하의 자녀를 가진 공무원은 36개월의 범위에서 자녀돌봄, 육아 등을 위해 1일 최대 2시간의 육아시간을 사용할 수 있음\n- 늦게 출근하거나, 일찍 퇴근 또는 근무시간 중 모두 활용 가능\n▸월 단위 이상 연속하여 사용하지 않으면 사용일수를 합산하여 20일마다 1개월을 사용한 것으로 계산\n▸기존 만1세 자녀돌봄 휴가를 사용한 경우 36개월 중 사용한 것으로 간주\n▸육아시간 사용 시 일(日) 최소 근무시간은 4시간 이상 되어야 하며 최소 근무시간 미충족 시 육아시간은 연가로 처리하여야 함\n▸육아시간 사용 시 근무시간 전·후에 시간외근무 가능"},{"id":"c04-w01-b35","title":"7. 재해구호 휴가","body":"▸재해구호 휴가일수: 5일 이내\n- 수해·화재·붕괴·폭발 등 재해피해를 입은 공무원\n- 재해지역에서 자원봉사 활동을 하고자 하는 공무원"},{"id":"c04-w01-b36","title":"8. 가족돌봄휴가","body":"▸가족돌봄 휴가일수: 10일 이내\n- ｢영유아보육법｣에 따른 어린이집, ｢유아교육법｣에 따른 유치원 및 ｢초･중등교육법｣ 제2조 각 호의 학교의 휴업ㆍ휴원ㆍ휴교, 그 밖에 이에 준하는 사유로 자녀 또는 손자녀를 돌봐야 하는 경우\n- 자녀 또는 손자녀가 다니는 어린이집등의 공식 행사 또는 교사와의 상담에 참여하는 경우\n- 미성년자 또는 ｢장애인복지법｣ 제2조제2항에 따른 장애인(이하 “장애인”이라 한다)인 자녀･손자녀의 병원 진료(｢국민건강보험법｣ 제52조에 따른 건강검진 또는 ｢감염병의 예방 및 관리에 관한 법률｣ 제24조 및 제25조에 따른 예방접종을 포함한다)에 동행하는 경우\n- 질병, 사고, 노령 등의 사유로 조부모, 외조부모, 부모(배우자의 부모를 포함한다), 배우자, 자녀 또는 손자녀를 돌봐야 하는 경우\n▸유급: 미성년 또는 장애인인 자녀의 경우에만 유급이며 시간단위 분할 사용 가능\n- 유급일수: 자녀 수 + 1일(단, 장애인 자녀 또는 한부모가족인 경우 1일 가산)\n▸무급: 미성년 또는 장애인인 자녀 이외의 경우로서 일 단위로만 사용 가능\n※ 부서장은 승인 시 증빙서류를 확인(학부모 알림장, 가정통신문, 진료확인서 등)\n※ 자녀가 2인 이상일 경우 자녀당 부여되는 것은 아님"},{"id":"c04-w01-b37","title":"9. 수업휴가","body":"▸연가일수를 초과하는 한국방송통신대학 출석 수업 기간\n▸본인의 법정연가일수를 먼저 사용한 후 부족한 일수에 한하여 수업휴가가 인정되므로 출석수업 전 연가사용은 불가피한 경우로 제한"},{"id":"c04-w01-b38","title":"10. 장기재직 휴가","body":"▸5년 이상 재직중인 지방공무원에 대하여 해당 재직 기간 중 허가\n재직기간 장기재직휴가일수 재직기간 장기재직휴가일수\n5년 이상 ~ 10년 미만 10년 이상 ~ 20년 미만 5일 15일 20년 이상 ~ 30년 미만 30년 이상 20일 25일\n※ 분할사용 시 1회 2일 이상 사용(시간 단위 사용 불가)\n※ 잔여일수가 2일 미만인 경우 자동소멸\n※ 해당 재직기간이 경과한 경우 미사용한 장기재직휴가는 자동 소멸, 이월 및 소급 사용불가","tables":[{"headers":[{"text":"재직기간","colSpan":1,"rowSpan":1,"column":0},{"text":"장기재직휴가일수","colSpan":1,"rowSpan":1,"column":1},{"text":"재직기간","colSpan":1,"rowSpan":1,"column":2},{"text":"장기재직휴가일수","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"5년 이상 ~ 10년 미만\n10년 이상 ~ 20년 미만","colSpan":1,"rowSpan":1,"column":0},{"text":"5일\n15일","colSpan":1,"rowSpan":1,"column":1},{"text":"20년 이상 ~ 30년 미만\n30년 이상","colSpan":1,"rowSpan":1,"column":2},{"text":"20일\n25일","colSpan":1,"rowSpan":1,"column":3}]],"widths":[27.54,22.77,26.92,22.77],"lineStart":1,"lineCount":2}]},{"id":"c04-w01-b39","title":"11. 새내기 휴가","body":"▸1년 이상 5년 미만 재직중인 지방공무원에 대하여 해당 재직 기간 중 허가\n▸해당 재직기간 중 3일 이내\n▸분할사용 시 1일 단위 분할사용 가능 사용\n▸해당 재직기간이 경과한 경우 미사용한 새내기휴가는 자동 소멸, 이월 및 소급 사용불가\n※ 근무상황 선택: 특별휴가-기타특별휴가-새내기휴가\n- 사유 또는 용무: ( )일차 새내기휴가(휴가목적, 재직기간 OO년)\n- 예시: 1일차 새내기휴가(가족여행, 재직기간 2년)"},{"id":"c04-w01-b40","title":"12. 학습휴가","body":"▸업무상 공백이 발생하지 않는 범위에서 연 7일 이내 허가.\n▸시간 단위 사용 불가(1회 최대 사용 가능 일수: 3일)\n▸학교근무자: 재량휴업일, 방학 등 휴업일에 제한하는 규정 삭제(2025.4.21.)\n▸기관근무자: 학습휴가 계획서 첨부규정 삭제(2025.4.21.)\n※ 근무상황 선택: 특별휴가-학습휴가\n- 사유 또는 용무: ( )일차 학습휴가(휴가 목적 기재)\n- 예시①: 1일차 학습휴가(자원봉사)\n- 예시②: 2일차 학습휴가(일본문화탐방, 공무외 국외여행)\n- 휴가기간 중 공무 외 국외여행을 하는 경우 ‘공무외 국외여행’임을 함께 표기"},{"id":"c04-w01-b41","title":"13. 입영동행 휴가","body":"▸배우자 또는 자녀의 입영 당일: 1일"},{"id":"c04-w01-b42","title":"14. 자녀보육 휴가","body":"▸4세 이하(매년 1월 1일 기준)의 자녀가 있는 공무원은 자녀 보육에 필요한 경우 연간 5일\n※ 부부공무원의 경우 부부가 합산하여 5일(자녀당 ×)"},{"id":"c04-w01-b43","title":"15. 심리안정휴가","body":"▸인명피해 사건·사고 경험으로 심리적 회복이 필요한 공무원에게 심리안정휴가(4일 이내) 부여\n- 사건·사고 발생 후 가급적 1개월 이내 범위에서 휴가 부여\n- 부여일수가 2일을 초과할 경우 전문상담사, 의사 등 관련 전문가 의견 필요"}],"flowGroups":[{"sourceText":"휴가신청 ⇒ 휴가허가 ⇒ 휴가승인"}]},{"id":"c04-w02","number":2,"title":"출장","formIds":["서식4"],"faqCategories":["출장"],"contentBlocks":[{"id":"c04-w02-b1","title":"업무 흐름도","body":"출장 신청 ⇒ 출장명령 ⇒ 출장실시"},{"id":"c04-w02-b2","title":"세부내용 출장","body":""},{"id":"c04-w02-b3","title":"관련법규 및 참고자료","body":"ㅊ\n• 「공무원 여비 규정」, 「국가공무원 복무·징계 관련 예규」, 「지방공무원 복무규정」"},{"id":"c04-w02-b4","title":"1. 출장","body":"▸정의: 학교장의 명을 받고 정규근무지 이외의 장소에서 공무를 수행하는 것\n※ 공무와 관련 없는 일에 대하여 출장 처리를 하여서는 안 됨\n▸출장 구분\n구분 대상\n국내출장 근무지내 같은 시 · 군 및 섬 안에서의 출장이나 여행거리가 12km 미만인 출장\n근무지외 근무지 내 이외의 국내출장\n국외출장 출장지가 국내가 아닌 다른 나라 출장","tables":[{"headers":[{"text":"구분","colSpan":2,"rowSpan":1,"column":0},{"text":"대상","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"국내출장","colSpan":1,"rowSpan":2,"column":0},{"text":"근무지내","colSpan":1,"rowSpan":1,"column":1},{"text":"같은 시 · 군 및 섬 안에서의 출장이나 여행거리가 12km 미만인 출장","colSpan":1,"rowSpan":1,"column":2}],[{"text":"근무지외","colSpan":1,"rowSpan":1,"column":1},{"text":"근무지 내 이외의 국내출장","colSpan":1,"rowSpan":1,"column":2}],[{"text":"국외출장","colSpan":1,"rowSpan":1,"column":0},{"text":"출장지가 국내가 아닌 다른 나라 출장","colSpan":2,"rowSpan":1,"column":1}]],"widths":[12.79,13.45,73.76],"lineStart":3,"lineCount":4}]},{"id":"c04-w02-b5","title":"2. 출장 신청","body":"▸공무원이 출장을 실시할 때는 사전에 근무상황부서식3 또는 출장신청서[서식4]에 의하여 소속기관장(위임전결규정에 의함)에게 허가를 받아야 함\n- 근무지내 출장: [나이스] 나의메뉴 → 복무 → 개인출장관리에서 신청\n- 근무지외 출장: [나이스] 나의메뉴 → 복무 → 개인출장관리에서 신청\n※ 전출자 근무상황조회: [나이스] 업무메뉴 → 복무 → 근무상황관리에서 과거자료조회 체크"},{"id":"c04-w02-b6","title":"TIP","body":"▪ 출장신청 후 정정 또는 삭제 방법\n▸출장신청이 완료된 경우\n- [나이스] 승인사항, 상신함에서 해당문서 클릭 후 기결문서취소 결재 요청 → 결재완료 후 상신함에서 해당문서 삭제 → 나의메뉴 → 복무에서 해당문서 삭제 후 다시 출장 신청 또는 변경 출장 신청\n▸출장신청 중인 경우\n- [나이스] 승인사항, 상신함에서 해당문서 클릭 후 회수 → 상신함에서 해당문서 삭제 → 나의메뉴→ 복무에서 해당문서 삭제 후 다시 출장 신청 또는 변경 출장 신청"},{"id":"c04-w02-b7","title":"3. 출장 명령","body":"▸출장 명령이 완료된 후 출장 실시(출장신청서에 출장 명령일이 표시됨)\n- 불가피한 사유로 사전에 허가를 받지 못한 경우, 사후에 지체 없이 허가를 받아야 함"},{"id":"c04-w02-b8","title":"4. 출장 실시","body":"▸출장 실시 전·후에 공무원여비규정에 근거하여 여비 지급"}],"flowGroups":[{"sourceText":"출장 신청 ⇒ 출장명령 ⇒ 출장실시"}]},{"id":"c04-w03","number":3,"title":"초과근무","formIds":["서식5","서식6","서식7"],"faqCategories":["초과근무"],"contentBlocks":[{"id":"c04-w03-b1","title":"업무 흐름도","body":"초과근무 신청 ⇒ 초과근무 명령 ⇒ 초과근무 확인"},{"id":"c04-w03-b2","title":"세부내용 초과근무","body":""},{"id":"c04-w03-b3","title":"관련법규 및 참고자료","body":"• 「공무원수당 등에 관한 규정」 제15조, 「공무원보수 등의 업무지침」\n• 「지방공무원보수업무 등 처리지침」"},{"id":"c04-w03-b4","title":"1. 초과근무 신청","body":"▸위치: [나이스] 기본메뉴 → 복무 → 개인초과근무관리에서 신청"},{"id":"c04-w03-b5","title":"2. 초과근무 명령","body":"▸초과근무 명령권자: 학교장"},{"id":"c04-w03-b6","title":"3. 초과근무 처리 절차","body":"초과근무 신청 ➡ 초과근무 명령 ➡ 초과근무 확인\n[나이스]를 이용한 초과근무 사전 신청 명령권자의 사전 승인 초과근무명령서[서식5] 초과근무명령대장[서식6] 초과근무 근무종료 후 (조기출근자는 출근 시) 초과근무확인대장[서식7] 자필 기재\n▸시간외수당을 지급받는 대신 해당 초과근무시간을 연가로 전환하여 사용 가능","tables":[{"headers":[{"text":"초과근무 신청","colSpan":1,"rowSpan":1,"column":0},{"text":"➡","colSpan":1,"rowSpan":2,"column":1},{"text":"초과근무 명령","colSpan":1,"rowSpan":1,"column":2},{"text":"➡","colSpan":1,"rowSpan":2,"column":3},{"text":"초과근무 확인","colSpan":1,"rowSpan":1,"column":4}],"rows":[[{"text":"[나이스]를 이용한\n초과근무 사전 신청","colSpan":1,"rowSpan":1,"column":0},{"text":"명령권자의 사전 승인\n초과근무명령서[서식5]\n초과근무명령대장[서식6]","colSpan":1,"rowSpan":1,"column":2},{"text":"초과근무 근무종료 후 (조기출근자는 출근 시) 초과근무확인대장[서식7] 자필 기재","colSpan":1,"rowSpan":1,"column":4}]],"widths":[21.44,3.75,28.47,3.93,42.41],"lineStart":0,"lineCount":2}]},{"id":"c04-w03-b7","title":"4. 초과근무 확인 및 마감 절차","body":"▸당직근무자 또는 복무관련 주관부서에서 확인대장 마감 → 당직담당부서에 인계\n▸초과근무 확인은 초과근무관리시스템 또는 무인경비연계시스템으로 운용\n▸전산시스템 이용 시 초과근무 다음날 초과근무 확인내역 결재 생략 가능\n▸다만, 매월 생성된 초과근무 내역 출력본 결재처리(월 1회)하여 급여 반영"},{"id":"c04-w03-b8","title":"5. 초과근무 확인","body":"▸위치: [나이스] 복무 → 개인 초과근무관리에서 확인\n- 초과근무명령서 및 확인대장(출·퇴근 결과)을 대조하여 초과근무시간 확인 입력\n▸출장 중 시간외근무: 학교장 판단 하에 교육과정 운영상 필요하다고 인정될 때에는 관계법령 및 지침에 따라 당일 총 근무한 시간이 드러나는 객관적인 증빙자료가 있는 경우에 한하여 지급 가능\n- 출장 중 시간외 근무 관련 사례\n순 관련 사례 인정 여부\n1 현장체험학습, 테마식 현장체험학습(수학여행), 수련활동과 이를 위해 평일 근무시간 이후 또는 휴무 토요일, 공휴일에 실시하는 사전 답사 O\n2 평일 근무시간 이후 또는 휴무 토요일, 공휴일에 대회에 참가하는 학생 인솔 등 O\n3 교직원 체육대회, 교직원 연수, 문화공연, 전국대회 참관 X","tables":[{"headers":[{"text":"순","colSpan":1,"rowSpan":1,"column":0},{"text":"관련 사례","colSpan":1,"rowSpan":1,"column":1},{"text":"인정 여부","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"1","colSpan":1,"rowSpan":1,"column":0},{"text":"현장체험학습, 테마식 현장체험학습(수학여행), 수련활동과 이를 위해 평일 근무시간 이후 또는 휴무 토요일, 공휴일에 실시하는 사전 답사","colSpan":1,"rowSpan":1,"column":1},{"text":"O","colSpan":1,"rowSpan":1,"column":2}],[{"text":"2","colSpan":1,"rowSpan":1,"column":0},{"text":"평일 근무시간 이후 또는 휴무 토요일, 공휴일에 대회에 참가하는 학생 인솔 등","colSpan":1,"rowSpan":1,"column":1},{"text":"O","colSpan":1,"rowSpan":1,"column":2}],[{"text":"3","colSpan":1,"rowSpan":1,"column":0},{"text":"교직원 체육대회, 교직원 연수, 문화공연, 전국대회 참관","colSpan":1,"rowSpan":1,"column":1},{"text":"X","colSpan":1,"rowSpan":1,"column":2}]],"widths":[6.88,81.34,11.78],"lineStart":4,"lineCount":4}]},{"id":"c04-w03-b9","title":"6. 초과근무 합산 반영","body":"▸위치: [나이스] 복무 → 초과근무 → 초과근무월별집계에서 월별 초과근무 생성 → 급여 반영"}],"flowGroups":[{"sourceText":"초과근무 신청 ⇒ 초과근무 명령 ⇒ 초과근무 확인"}]},{"id":"c04-w04","number":4,"title":"유연근무제","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c04-w04-b1","title":"업무 흐름도","body":"유연근무제 신청 ⇒ 유연근무제 승인 ⇒ 유연근무제 확인(관리)"},{"id":"c04-w04-b2","title":"세부내용 유연근무제","body":""},{"id":"c04-w04-b3","title":"관련법규 및 참고자료","body":"• 「지방공무원 복무규정」 제3조, 「지방공무원 복무에 관한 예규」"},{"id":"c04-w04-b4","title":"1. 유연근무제 유형","body":"▸탄력근무제: 주40시간 근무하되, 출퇴근시각 ･ 근무시간 ･ 근무일을 자율 조\n▸원격근무제: 특정한 근무장소를 정하지 않고 정보통신망을 이용하여 근무\n유 형 활용 방법 비고\n탄력 근무제 시차출퇴근형 1일 8시간 근무(출퇴근시간 자율조정) 주 40시간 근무\n근무시간선택형 1일 4~12시간 근무, 주 5일 근무 준수\n집약근무형 1일 4~12시간 근무, 주 3.5~4일 근무\n재량 근무제 근무시간, 근무장소에 구애없이 근무(프로젝트 수행) 주 40시간 인정\n원격 근무제 재택근무형 사무실이 아닌 자택에서 근무\n스마트워크근무형 자택 인근 스마트워크센터 등 별도 사무실에서 근무\n▸단, 공무직의 경우 나이스가 아닌 업무관리시스템 내부기안 결재 후 유연근무제 운영","tables":[{"headers":[{"text":"유 형","colSpan":2,"rowSpan":1,"column":0},{"text":"활용 방법","colSpan":1,"rowSpan":1,"column":2},{"text":"비고","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"탄력 근무제","colSpan":1,"rowSpan":3,"column":0},{"text":"시차출퇴근형","colSpan":1,"rowSpan":1,"column":1},{"text":"1일 8시간 근무(출퇴근시간 자율조정)","colSpan":1,"rowSpan":1,"column":2},{"text":"주 40시간 근무","colSpan":1,"rowSpan":3,"column":3}],[{"text":"근무시간선택형","colSpan":1,"rowSpan":1,"column":1},{"text":"1일 4~12시간 근무, 주 5일 근무 준수","colSpan":1,"rowSpan":1,"column":2}],[{"text":"집약근무형","colSpan":1,"rowSpan":1,"column":1},{"text":"1일 4~12시간 근무, 주 3.5~4일 근무","colSpan":1,"rowSpan":1,"column":2}],[{"text":"재량 근무제","colSpan":2,"rowSpan":1,"column":0},{"text":"근무시간, 근무장소에 구애없이 근무(프로젝트 수행)","colSpan":1,"rowSpan":1,"column":2},{"text":"주 40시간 인정","colSpan":1,"rowSpan":1,"column":3}],[{"text":"원격\n근무제","colSpan":1,"rowSpan":2,"column":0},{"text":"재택근무형","colSpan":1,"rowSpan":1,"column":1},{"text":"사무실이 아닌 자택에서 근무","colSpan":1,"rowSpan":1,"column":2},{"text":"","colSpan":1,"rowSpan":1,"column":3}],[{"text":"스마트워크근무형","colSpan":1,"rowSpan":1,"column":1},{"text":"자택 인근 스마트워크센터 등 별도 사무실에서 근무","colSpan":1,"rowSpan":1,"column":2},{"text":"","colSpan":1,"rowSpan":1,"column":3}]],"widths":[8.81,15.97,57.12,18.1],"lineStart":2,"lineCount":7}]},{"id":"c04-w04-b5","title":"2. 시차출퇴근형 운영","body":"▸1일 법정 근무시간인 8시간의 근무체제를 유지하면서, 자신의 출근시간을 결정할 수 있게 하는 제도로 의무적으로 근무해야 하는 공동근무시간대(Core Time)와 자유로이 근무여부를 결정할 수 있는 탄력적 시간대(Flexible Time)로 나누어 운영\n시차 출 · 퇴근제 개념도(기관 예시)\n07:00 10:00 12:00 13:00 16:00 19:00\n탄력시간 (Flexible Time) 공동근무시간 (Core Time) 중식시간 공동근무시간 (Core Time) 탄력시간 (Flexible Time)\n전체근무시간\n▸기관·부서 간 업무협조 및 민원인 불편을 최소화하기 위해 공동근무시간대(Core Time)를 설정(예: 10:00~16:00)하여 이 시간에는 모든 직원이 근무할 수 있도록 함\n- 다만, 분장업무의 특성상 공동근무시간에 구애 받지 않아도 되는 경우에는 예외를 인정\n▸1개월 이상 단위로 신청하며 실시 7일 전까지 부서장(기관) 및 학교장(학교)의 승인을 받아야 함\n▸시차 출·퇴근제의 신청·해제는 해당 공무원의 신청이 원칙\n▸07:00∼10:00까지 30분 단위로 출근 유형을 정하고 운영하는 것을 원칙으로 하되, 국민서비스 확대, 시간대별 행정수요 탄력대응, 에너지절약 등 해당 행정기관의 업무특성상 필요한 경우 다양하게 운영할 수 있음\n- 또한, 요일마다 다른 출근시간을 선택하는 요일별 시차 출·퇴근제도 가능\n※ 기관 예시: 화∼목요일은 9∼18시, 금요일은 7∼16시, 월요일은 10∼19시 근무\n▸각급 기관(학교)장은 초과근무관리시스템 등 출·퇴근 시간을 확인할 수 있는 장비를 활용하여 출·퇴근 시간 확인 철저","tables":[{"headers":[{"text":"","colSpan":2,"rowSpan":1,"column":0},{"text":"시차 출 · 퇴근제 개념도(기관 예시)","colSpan":6,"rowSpan":2,"column":2},{"text":"","colSpan":3,"rowSpan":1,"column":8}],"rows":[[{"text":"","colSpan":2,"rowSpan":1,"column":0},{"text":"","colSpan":3,"rowSpan":1,"column":8}],[{"text":"07:00 10:00 12:00 13:00 16:00 19:00","colSpan":11,"rowSpan":1,"column":0}],[{"text":"","colSpan":1,"rowSpan":1,"column":0},{"text":"탄력시간\n(Flexible Time)","colSpan":2,"rowSpan":1,"column":1},{"text":"공동근무시간\n(Core Time)","colSpan":2,"rowSpan":1,"column":3},{"text":"중식시간","colSpan":1,"rowSpan":1,"column":5},{"text":"공동근무시간\n(Core Time)","colSpan":3,"rowSpan":1,"column":6},{"text":"탄력시간\n(Flexible Time)","colSpan":1,"rowSpan":1,"column":9},{"text":"","colSpan":1,"rowSpan":1,"column":10}],[{"text":"","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":3,"rowSpan":1,"column":1},{"text":"전체근무시간","colSpan":3,"rowSpan":2,"column":4},{"text":"","colSpan":3,"rowSpan":1,"column":7},{"text":"","colSpan":1,"rowSpan":1,"column":10}],[{"text":"","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":3,"rowSpan":1,"column":1},{"text":"","colSpan":3,"rowSpan":1,"column":7},{"text":"","colSpan":1,"rowSpan":1,"column":10}]],"picture":true,"widths":[1.88,9.55,9.29,9.29,9.29,15.12,9.29,9.29,7.16,17.98,1.88],"lineStart":1,"lineCount":4},{"headers":[{"text":"※ 기관 예시: 화∼목요일은 9∼18시, 금요일은 7∼16시, 월요일은 10∼19시 근무","colSpan":1,"rowSpan":1,"column":0}],"rows":[],"widths":[100],"lineStart":11,"lineCount":1}]}],"flowGroups":[{"sourceText":"유연근무제 신청 ⇒ 유연근무제 승인 ⇒ 유연근무제 확인(관리)"}]},{"id":"c04-w05","number":5,"title":"외부강의 등","formIds":[],"faqCategories":["외부강의 등"],"contentBlocks":[{"id":"c04-w05-b1","title":"업무 흐름도","body":"외부강의 등 요청 ⇒ 외부강의 등 신고 ⇒ 외부강의 등 허가"},{"id":"c04-w05-b2","title":"세부내용 외부강의 등","body":""},{"id":"c04-w05-b3","title":"관련법규 및 참고자료","body":"• 「부정청탁 및 금품 등 수수금지에 관한 법률」 제10조\n• 「지방공무원 복무규정」 제10조, 제11조"},{"id":"c04-w05-b4","title":"1. 외부강의(강의 · 발표 · 토론 · 심사 등) 신고","body":"▸소속 기관의 장(기관장은 행동강령책임관에게)에게 전자문서시스템을 활용하여 신고\n▸사례금을 받는 외부강의만 대상(외부강의 등을 마친 날로부터 10일 이내)\n▸외부강의 요청자가 국가나 지방자치단체(소속기관 포함)인 경우는 신고대상 아님"},{"id":"c04-w05-b5","title":"2. 전북특별자치도교육청 외부강의 대가 기준","body":"(단위: 천원 / 시간당)\n구 분 교육감 이하 공무원과 공직유관단체 및 기관의 장과 임직원 각급 학교의 장과 교직원 및 학교법인의 임직원 비고\n상한액 400 1,000 (실비 수준의) 여비 등은 미포함\n▸외부강의 대가 기준은 시간당 상한액으로, 기준을 초과하여 수수할 수 없음\n▸상한액 초과 수령 시 해당기관에 즉시 반환하고 기관의 장에게 신고(초과 사례금 신고서)","tables":[{"headers":[{"text":"구 분","colSpan":1,"rowSpan":1,"column":0},{"text":"교육감 이하 공무원과 공직유관단체 및 기관의 장과 임직원","colSpan":1,"rowSpan":1,"column":1},{"text":"각급 학교의 장과 교직원 및 학교법인의 임직원","colSpan":1,"rowSpan":1,"column":2},{"text":"비고","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"상한액","colSpan":1,"rowSpan":1,"column":0},{"text":"400","colSpan":1,"rowSpan":1,"column":1},{"text":"1,000","colSpan":1,"rowSpan":1,"column":2},{"text":"(실비 수준의) 여비 등은 미포함","colSpan":1,"rowSpan":1,"column":3}]],"widths":[12.79,16.2,33.32,37.69],"lineStart":1,"lineCount":2}]},{"id":"c04-w05-b6","title":"3. 겸직허가: 대학(교)의 시간강사 ․ 겸임교수 출강(겸직허가 신청서)","body":"▸대가의 유무 및 월간 강의 횟수와 관계없이 1월을 초과하여 지속적으로 출강 시"},{"id":"c04-w05-b7","title":"4. 외부강의 등 신고 절차도","body":"요청기관의 공문에 의한 정당한‘외부강의등’신청인가? ➡ No ‘외부강의 등’ 불가\n⇩Yes\n직무연관성 및 업무형편, 공정한 직무 수행에 지장이 없는가? ➡ No ‘외부강의 등’ 불가\n⇩Yes\n모든 ‘외부강의 등’소속 기관 장의 사전결재(필수) ※ 국가공무원 복무‧징계에 관한 예규에 따라 모든 외부강의는 사전결재를 받은 후 출강\n⇩\n‘외부강의 등’ 요청기관이 국가 / 지자체 / 그 소속기관인가? ➡ No 신고대상 ※ 사례금을 받는 외부강의에 대해 10일 이내에 신고 ※ 방법: 나이스→외부강의등록\n⇩Yes\n신고대상 아님\n⇩\n외부강의 등 출강 시 복무직무와 관련이 있거나 국가정책수행 목적상 필요한가? ➡ No 연가 ‧ 외출 ‧ 조퇴 처리\n⇩Yes\n출장 처리(강의 요청기관이 여비 등 지급 시 여비 부지급)","tables":[{"headers":[{"text":"요청기관의 공문에 의한 정당한‘외부강의등’신청인가?","colSpan":1,"rowSpan":1,"column":0},{"text":"➡\nNo","colSpan":1,"rowSpan":1,"column":1},{"text":"‘외부강의 등’ 불가","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"⇩Yes","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"직무연관성 및 업무형편, 공정한 직무 수행에 지장이 없는가?","colSpan":1,"rowSpan":1,"column":0},{"text":"➡\nNo","colSpan":1,"rowSpan":1,"column":1},{"text":"‘외부강의 등’ 불가","colSpan":1,"rowSpan":1,"column":2}],[{"text":"⇩Yes","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"모든 ‘외부강의 등’소속 기관 장의 사전결재(필수)\n※ 국가공무원 복무‧징계에 관한 예규에 따라 모든 외부강의는 사전결재를 받은 후 출강","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"⇩","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"‘외부강의 등’ 요청기관이\n국가 / 지자체 / 그 소속기관인가?","colSpan":1,"rowSpan":1,"column":0},{"text":"➡\nNo","colSpan":1,"rowSpan":1,"column":1},{"text":"신고대상\n※ 사례금을 받는 외부강의에 대해 10일 이내에 신고\n※ 방법: 나이스→외부강의등록","colSpan":1,"rowSpan":1,"column":2}],[{"text":"⇩Yes","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"신고대상 아님","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"⇩","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"외부강의 등 출강 시 복무직무와 관련이 있거나\n국가정책수행 목적상 필요한가?","colSpan":1,"rowSpan":1,"column":0},{"text":"➡\nNo","colSpan":1,"rowSpan":1,"column":1},{"text":"연가 ‧ 외출 ‧ 조퇴 처리","colSpan":1,"rowSpan":1,"column":2}],[{"text":"⇩Yes","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"출장 처리(강의 요청기관이 여비 등 지급 시 여비 부지급)","colSpan":1,"rowSpan":1,"column":0},{"text":"","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}]],"widths":[61.38,6.63,31.99],"lineStart":0,"lineCount":13}]}],"flowGroups":[{"sourceText":"외부강의 등 요청 ⇒ 외부강의 등 신고 ⇒ 외부강의 등 허가"}]},{"id":"c04-w06","number":6,"title":"당직 및 비상근무","formIds":["서식1","서식2","예시1","예시2","예시3"],"faqCategories":["당직 및 비상근무"],"contentBlocks":[{"id":"c04-w06-b1","title":"업무 흐름도","body":"당직 및 비상근무 계획 ⇒ 당직 및 비상근무 실시"},{"id":"c04-w06-b2","title":"세부내용 1. 당직 및 비상근무 계획","body":""},{"id":"c04-w06-b3","title":"관련법규 및 참고자료","body":"• 「전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙」"},{"id":"c04-w06-b4","title":"1. 당직의 구분","body":"▸근무시간별: 일직과 숙직\n▸근무장소별: 일반당직과 재택당직"},{"id":"c04-w06-b5","title":"2. 당직 및 비상근무 내부계획(규정) [예시1] 수립","body":"▸학교(기관) 실정에 맞는 당직방법 설정 운영\n▸당직실, 당직 근무시간, 인원, 임무 등 지정"},{"id":"c04-w06-b6","title":"3. 당직 및 비상근무 운영 방법","body":"▸당직위탁운영계약예시2\n- 경비업법에 의해 인가된 경비용역업체와 계약\n- 경비용역업체 근무자와 직원 간 비상연락 체계 강구\n- 위탁업체 근무자의 당직 근무 책임 등은 당해 직원 당직의 경우와 동일\n▸경비원 직접고용 노동(근로)계약예시3\n- 사업부서의 경비원 정원 승인 후 신규채용(만 55세 이상자 채용, 정년 65세) 가능"},{"id":"c04-w06-b7","title":"4. 당직실 설치","body":"▸방범 ․ 방호 ․ 방화 등 당직 근무상황에 가장 적합한 위치에 당직실 설치 운영\n▸당직 근무자와 직원 간 비상연락 체계 강구"},{"id":"c04-w06-b8","title":"TIP","body":"▪ 당직실 주요 비품\n▸당직근무일지 ▸기관 간 비상연락 체계도 ▸관계기관 당직실 전화번호부 ▸비상열쇠 보관함\n▸직원 및 민방위대원 비상소집 명부 → 전화 · 도보 · 교통수단 등의 연락방법 2가지 이상 기재\n▸당직 및 비상근무규칙 ▸안전 지출 파기 계획 ▸기타 당직에 필요한 물품"},{"id":"c04-w06-b9","title":"5. 당직의 미운영","body":"▸당직근무대상인원이 적어 1명이 당직근무를 하여도 당직근무 횟수가 1명당 2주 1회를 초과하는 경우로써, 근무시간 외에는 문서처리 및 업무연락 등의 필요성이 적은 경우에 한하여 다음의 보완대책을 강구한 후 당직근무 미실시\n- 기관별 무인전자경비장치 등 보안장비 설치\n- 착신통화전환 또는 당직용 이동전화 확보 등 통신연락체계 강구\n- 긴급사태시 업무연락 등 대응조치 강구\n- 최종 퇴청자는 전열기 점검 및 문단속 등 완벽한 보안점검 책임 이행"},{"id":"c04-w06-b10","title":"세부내용 2. 당직근무","body":""},{"id":"c04-w06-b11","title":"관련법규 및 참고자료","body":"• 「전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙」"},{"id":"c04-w06-b12","title":"1. 당직신고","body":"▸당직근무자는 당직근무 개시 30분 전에 당직명령자에게 신고\n- 토요일 ․ 공휴일의 당직은 그 직전 정상근무일에 신고\n▸당직자는 복장 단정 및 당직근무표찰[별표1] 패용"},{"id":"c04-w06-b13","title":"2. 당직의 인계 · 인수","body":"▸(당직근무 실시 전) 당직 주무부서로부터 당직근무일지[서식1] 및 기타 당직 시 필요 비품 인수 ․ 확인\n▸(당직근무 종료 후) 당직 주무부서에 인계 (휴무일의 경우 당직근무자 간 인계 ․ 인수)"},{"id":"c04-w06-b14","title":"3. 당직근무자 일반업무","body":"▸방범, 방호, 방화, 그 밖의 보안상태의 점검 → 실별 보안점검표[서식2] 확인\n▸경비원 및 시간외 근무자에 대한 복무상태 점검\n▸문서의 수발 ․ 인계 또는 관리\n▸국기 게양 및 관리상태 점검\n▸전화 민원 응대\n▸비상근무 발령 시 소속 공무원 비상소집 등 조치\n- 당직근무자는 당직근무 중에 접수된 문서나 발생한 업무가 비상소집 등 긴급한 처리를 요하는 사항일 때에는 이를 지체 없이 주무부서에 연락하거나 소속기관장에게 보고하고 필요한 조치를 하여야 함"},{"id":"c04-w06-b15","title":"4. 긴급사태 시 당직근무자의 임무","body":"▸화재 발생 시\n- 기관 내의 화재경보\n- 관할 소방서에 연락\n- 자체 소화시설에 의한 진화작업\n- 소속기관장 또는 상급기관 보고 후 조치\n▸외부침입자 등이 있을 때\n- 경찰서 등 유관기관에 연락\n- 중요시설의 경비 강화\n- 소속기관장 또는 상급기관 보고 후 조치\n⇒ 당직근무자는 긴급한 사태가 발생한 경우에는 그 상황에 따라 소속기관의 장이나 상급기관의 당직근무자에게 지체 없이 이를 보고하고 그의 지시를 받아 필요한 조치를 하여야 함. 다만 특히 긴급을 요하여 상급기관의 장 등의 지시를 기다릴 시간적 여유가 없을 때에는 긴급사태 발생 보고와 함께 필요한 조치를 한 후 지체 없이 그 경과를 보고해야 함"},{"id":"c04-w06-b16","title":"5. 당직근무 종료","body":"▸당직근무가 종료되면 당직비품 인계"},{"id":"c04-w06-b17","title":"세부내용 3. 비상근무","body":""},{"id":"c04-w06-b18","title":"관련법규 및 참고자료","body":"• 「전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙」"},{"id":"c04-w06-b19","title":"1. 개요","body":"▸정의: 비상사태에 효율적으로 대처하기 위해 비상근무명령이 발령된 상황에서 근무하는 것\n▸비상근무의 종류\n구분 종류\n비상근무 제1호 ◦ 전시, 사변 또는 이에 준하는 비상사태가 발생하였거나 발생이 임박하여 긴장이 최고조에 이른 경우\n비상근무 제2호 ◦ 전시, 사변 또는 이에 준하는 비상사태와 관련된 긴장이 고조된 경우나 천재지변, 그 밖에 이에 준하는 사유로 사회불안이 조성되고 사회질서가 교란될 우려가 있는 경우\n비상근무 제3호 ◦ 전시, 사변 또는 이에 준하는 비상사태와 관련된 징후가 현저히 증가된 경우 ◦ 적의 국지(局地)도발이 있는 경우로서 비상근무 제1호 또는 비상근무 제2호의 발령 단계에 이르지 않은 경우 ◦ 천재지변, 그 밖에 이에 준하는 사유로 긴급한 대응이 필요하다고 판단되는 경우\n비상근무 제4호 ◦ 제1호부터 제3호 이외에 위기상황에 신속 대응할 필요가 있거나 재해 · 재난 등의 긴급상황 발생 등으로 비상근무가 필요하다고 인정된 경우","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"종류","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"비상근무 제1호","colSpan":1,"rowSpan":1,"column":0},{"text":"◦ 전시, 사변 또는 이에 준하는 비상사태가 발생하였거나 발생이 임박하여 긴장이 최고조에 이른 경우","colSpan":1,"rowSpan":1,"column":1}],[{"text":"비상근무 제2호","colSpan":1,"rowSpan":1,"column":0},{"text":"◦ 전시, 사변 또는 이에 준하는 비상사태와 관련된 긴장이 고조된 경우나 천재지변, 그 밖에 이에 준하는 사유로 사회불안이 조성되고 사회질서가 교란될 우려가 있는 경우","colSpan":1,"rowSpan":1,"column":1}],[{"text":"비상근무 제3호","colSpan":1,"rowSpan":1,"column":0},{"text":"◦ 전시, 사변 또는 이에 준하는 비상사태와 관련된 징후가 현저히 증가된 경우\n◦ 적의 국지(局地)도발이 있는 경우로서 비상근무 제1호 또는 비상근무 제2호의 발령 단계에 이르지 않은 경우\n◦ 천재지변, 그 밖에 이에 준하는 사유로 긴급한 대응이 필요하다고 판단되는 경우","colSpan":1,"rowSpan":1,"column":1}],[{"text":"비상근무 제4호","colSpan":1,"rowSpan":1,"column":0},{"text":"◦ 제1호부터 제3호 이외에 위기상황에 신속 대응할 필요가 있거나 재해 · 재난 등의 긴급상황 발생 등으로 비상근무가 필요하다고 인정된 경우","colSpan":1,"rowSpan":1,"column":1}]],"widths":[16.64,83.36],"lineStart":2,"lineCount":5}]},{"id":"c04-w06-b20","title":"2. 비상소집 및 연락체계","body":"▸비상소집\n비상근무 발령\n전북특별자치도 전역 또는 일정지역을 대상\n⇩\n비상소집\n당직자 → 기관장에게 보고 → 직원 비상연락 소집\n⇩\n비상근무 결과 보고\n기관장 → 상급감독 기관장\n▸국가 비상 연락 체계\n- 행정안전부장관 → 당직 총사령실 → 당직사령 및 부처별 당직자 → 관할기관 ․ 소속기관 ․ 피감독기관의 당직자 → 소속직원","tables":[{"headers":[{"text":"비상근무 발령","colSpan":1,"rowSpan":1,"column":0}],"rows":[[{"text":"전북특별자치도 전역 또는 일정지역을 대상","colSpan":1,"rowSpan":1,"column":0}],[{"text":"⇩","colSpan":1,"rowSpan":1,"column":0}],[{"text":"비상소집","colSpan":1,"rowSpan":1,"column":0}],[{"text":"당직자 → 기관장에게 보고 → 직원 비상연락 소집","colSpan":1,"rowSpan":1,"column":0}],[{"text":"⇩","colSpan":1,"rowSpan":1,"column":0}],[{"text":"비상근무 결과 보고","colSpan":1,"rowSpan":1,"column":0}],[{"text":"기관장 → 상급감독 기관장","colSpan":1,"rowSpan":1,"column":0}]],"widths":[100],"lineStart":1,"lineCount":8}]},{"id":"c04-w06-b21","title":"3. 비상근무의 방법","body":"▸휴일과 야간 근무 시\n구분 근무요령\n비상근무 제1호 연가를 중지하고 소속 직원 1 / 3이상 비상근무\n비상근무 제2호 연가를 중지하고 소속 직원 1 / 5이상 비상근무\n비상근무 제3호 연가를 억제하고 소속 직원 1 / 10이상 비상근무\n비상근무 제4호 연가를 억제하고 소속기관장이 정하는 바에 따라 비상근무\n▸비상근무 기간 중에는 소속직원의 출장을 억제하고 항상 소속직원의 소재 파악\n▸비상근무 인원이 특정부서에 편중되지 않도록 하고 문서보관자, 통신요원 등 사무보조에 필요한 인원 등을 포함","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"근무요령","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"비상근무 제1호","colSpan":1,"rowSpan":1,"column":0},{"text":"연가를 중지하고 소속 직원 1 / 3이상 비상근무","colSpan":1,"rowSpan":1,"column":1}],[{"text":"비상근무 제2호","colSpan":1,"rowSpan":1,"column":0},{"text":"연가를 중지하고 소속 직원 1 / 5이상 비상근무","colSpan":1,"rowSpan":1,"column":1}],[{"text":"비상근무 제3호","colSpan":1,"rowSpan":1,"column":0},{"text":"연가를 억제하고 소속 직원 1 / 10이상 비상근무","colSpan":1,"rowSpan":1,"column":1}],[{"text":"비상근무 제4호","colSpan":1,"rowSpan":1,"column":0},{"text":"연가를 억제하고 소속기관장이 정하는 바에 따라 비상근무","colSpan":1,"rowSpan":1,"column":1}]],"widths":[23.94,76.06],"lineStart":1,"lineCount":5}]}],"flowGroups":[{"sourceText":"당직 및 비상근무 계획 ⇒ 당직 및 비상근무 실시"}]}],"forms":[{"id":"서식1","title":"당직근무일지","content":"[서식1]\n\n \n 당직근무일지 \n (앞쪽) \n . . .( 요일 [ ]숙 직) 결재 \n [ ]일 \n 당 직 자 당직명 소속 직위 (직급) 성명 서명 문서처리상황 \n 종류 발송 접수 인계 비고 \n 문서 번호 수신처 제목 \n \n 지시받은사항 조치 사항 \n \n \n 지시한 사항 조치 결과 확인 특근자현황 \n 소속ㆍ부서 인원수 특근시간 \n 외 명 \n 외 명 \n 보고 사항 인계 사항 1.물품 2.문서 3.기타 외 명 \n 외 명 \n 외 명 \n 210mm×297mm[일반용지 60g/㎡(재활용품)] \n \n\n \n (뒤 쪽) \n 청사 내의 순찰점검사항 \n 순찰시간 발견 사실 및 처리개요 순찰자 순찰시간 발견 사실 및 처리개요 순찰자 \n 시 분부터 시 분까지 (서명) 시 분부터 시 분까지 (서명) \n 시 분부터 시 분까지 (서명) 시 분부터 시 분까지 (서명) \n 연락사항 연락기관 수화자 소속 ㆍ직위(직급) 수화자 성명 송화자 성명 이상 유무 \n \n \n \n \n \n \n \n \n \n \n 비고 \n \n\n\n!image\n\n\n!image","sectionId":"c04-w06"},{"id":"서식2","title":"보 안 점 검 표","content":"[서식2]\n\n 보 안 점 검 표 \n\n년도 실․과명:\n\n \n 구분 점검일 ①서류보관상태 ②청소상태 ③소등상태 ④화기단속상태 ⑤문단속상태 ⑥ 비 고 점검시각 및 점검자 결 재 \n 최 종 퇴청자 당 직 근무자 최 종 퇴청자 당 직 근무자 최 종 퇴청자 당 직 근무자 최 종 퇴청자 당 직 근무자 최 종 퇴청자 당 직 근무자 최종퇴청자 당직근무자 \n 점검시각 성명 점검시각 성명 \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n\n※ 비고\n\n1. 서류보관상태: 책상위 서류방치 여부와 캐비닛, 책상 등의 잠금여부\n\n2. 화기단속상태: 컴퓨터․프린터․복사기․선풍기 및 전열기(커피포트․전기히터 등)의 전원스위치 차단 여부와 배선주변에 인화 물질이 있는지 여부\n\n\n!image\n\n\n!image","sectionId":"c04-w06"},{"id":"서식3","title":"근무상황부","content":"[서식3]\n\n \n 근무상황부 \n (부서: 직급: 성명: ) \n 종별 기간 또는 일시 사유 또는 용무 연락처 (전화번호) 결재 \n 부터 까지 일수․ 시간 \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n ※ 비고 1. 종별은 휴가(연가․병가․공가․특별휴가)․지참․조퇴․외출․출장 및 결근 등을 기재함 2. 지참․조퇴 및 외출의 경우 질병․부상 등 그 사유를 반드시 기재하도록 하고, 이 경우 “부터”란은 일․시․분을, “까지”란은 시․분을 기재하되, 불가피한 사유로 기재사항의 변경이 필요한 경우에는 사후에 정정하여 결재권자에게 보고함 \n \n\n\n!image\n\n\n!image","sectionId":"c04-w01"},{"id":"서식4","title":"출장신청서","content":"[서식4]\n\n \n 출장신청서 20 . . . \n 결제 협조 \n \n 다음과 같이 출장을 명함 \n 직급 성명 출장목적 출장기간 출장지 서명 또는 날인 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 부터 ( ) 까지 \n 이동사항: \n 여비 정산 \n \n\n\n!image\n\n\n!image","sectionId":"c04-w02"},{"id":"서식5","title":"초 과 근 무 명 령 서","content":"[서식5]\n\n 초 과 근 무 명 령 서 \n\n \n 연 번 부서명: 국(실) 과(20 . . .) 담 당 실ㆍ국장(과장) 부단체장(국장) 결 재 \n \n \n 직급 성명 초과근무명령사항 비 고 \n 구 분 근무시간 하여야 할 일(구체적으로) 처리시한 \n : 부터 : 까지 월 일 \n \n \n \n \n \n \n \n \n \n \n \n \n\n당직자 확인(사후결재시) 직 성명 (서명)\n\n※ 연번은 초과근무명령대장의 연번과 일치하게 기재, 구분란은 시간외, 야간, 휴일로 기재\n\n※ 결재권자는 반드시 자필서명에 의하여 결재\n\n※ 명령받은 시간과 실제 근무한 시간이 상이한 경우에는 실제 근무시간을 ‘비고’란에 기재\n\n\n!image\n\n\n!image","sectionId":"c04-w03"},{"id":"서식6","title":"초 과 근 무 명 령 대 장","content":"[서식6]\n\n 초 과 근 무 명 령 대 장 \n\n20 년 월분\n\n \n 연번 일자 부서명 근무자현황 비 고 \n 종 류 근무인원 근무자명단(시간) \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n\n※ 시간외근무의 경우, 근무자 명단에 개인별로 금회 시간외근무시간을 ( )에 기재\n\n종류는 시간외, 야간, 휴일로 표시\n\n\n!image\n\n\n!image","sectionId":"c04-w03"},{"id":"서식7","title":"초 과 근 무 확 인 대 장","content":"[서식7]\n\n 초 과 근 무 확 인 대 장 \n\n \n 년월일 소 속 직 급 성 명 근무현황 근무자 서 명 당직자 서 명 \n 출근시간 퇴근시간 \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n\n \n\n1. 각 란은 초과근무를 한 공무원 본인이 직접 기재하여야 함\n\n2. ‘출근시간’란은 정규근무일이 아닌 날에 출근하여 근무한 경우와 1시간 이상 조기 출근한 경우에만 기재\n\n3. 당직근무자는 당직 개시 전 당직담당부서에서 대장을 인수하여 출입구 또는 당직실 등 초과근무자가 기재하기 용이한 장소에 비치\n\n4. 당직근무자는 초과근무자 근무내역 자필 기재 시 본인 여부 확인 후 서명하고, 당직 종료 후 매일의 초과근무현황을 마감(최종퇴청자 바로 아래란에 근무 년ㆍ월ㆍ일 및 초과근무인원을 기재한 후 직, 성명을 기재)하여 당직담당부서에 인계\n\n\n!image\n\n\n!image","sectionId":"c04-w03"},{"id":"예시1","title":"○○학교 당직 및 비상근무 규정(예시)","content":"[예시1]\n\n ○○학교 당직 및 비상근무 규정(예시) \n\n제1조(목적) 이 규정은 국가공무원 당직 및 비상근무 규칙 제2조 및 전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙에 따라 OO학교 당직 및 비상근무에 관하여 필요한 사항을 규정함을 목적으로 한다.\n\n\n 제2조(적용범위) 이 규정의 적용 대상은 OO학교로 한다.\n\n\n 제3조(당직의 구분)\n\n①당직은 위탁운영을 기본으로 한다.\n\n②당직근무자(당직위탁운영에 의한 경비용역업체의 근무자, 이하 “당직근무자”라 한다)의 근무시간은 다음의 각 호와 같다.\n\n1. 평일: 16:30 \\~ 익일: 08:30\n\n2. 토요일, 공휴일: 08:30 \\~ 익일: 08:30\n\n(단, 임시공휴일 및 임시휴교일, 개교기념일을 포함한다.)\n\n\n 제4조(당직신고 및 인계․인수)\n\n①당직근무자는 당직근무 개시시간 30분 전에 당직명령자에게 당직신고를 하여야 한다.\n\n②당직근무자는 제1항의 당직신고 전에 당직 주무부서로부터 당직근무일지 기타 필요한 당직용 비품을 인수․확인하여야 하고, 당직근무를 마칠 때에는 이를 당직 주무부서에 인계하여야 한다.\n\n\n 제5조(당직근무자의 준수사항)\n\n①당직근무자는 근무상의 공무 아닌 용무로 근무구역을 이탈하여서는 아니 되며, 당직자로서의 품위를 손상하거나 당직근무에 지장이 있는 행위를 하여서는 아니 된다.\n\n②당직근무자는 복장을 단정히 하여야 하고, 당직근무표찰을 패용하여야 한다.\n\n제6조(당직실의 위치) 학교장은 방범․방호․방화 등 당직근무수행에 가장 적합한 위치에 당직실을 설치․운영하여야 한다.\n\n제7조(당직실 전화시설) 당직실에는 전화시설을 하고, 그 전화번호를 관할체신관서 및 관계기관에 통보하여야 한다.\n\n\n 제8조(당직근무자의 일반업무)\n\n①당직근무자는 다음 각 호의 사항을 성실히 이행함으로써 사고의 발생을 미연에 방지하여야 한다.\n\n1. 방범․방호․방화 기타 보안상태의 순찰․점검\n\n2. 경비원 기타 정상근무시간외의 근무자에 대한 복무상태의 점검\n\n3. 문서의 수발․인계 또는 관리\n\n4. 국기의 게양 및 관리상태의 점검\n\n5. 전화민원의 응대\n\n②학교장은 사무실별로 보안점검표를 작성비치하고 최종퇴청자가 이를 점검하도록 하여야 하며, 당직근무자는 학교장이 지정한 사무실에 대하여 최종퇴청자가 기록한 점검사항을 확인하여야 한다. 다만, 당직근무자는 무인전자경비장치 등 보안장비가 작동 중인 보호구역안의 보안점검표 점검사항은 이를 확인하지 아니할 수 있다.\n\n③당직근무자는 당직근무 중에 접수된 문서나 발생한 업무가 긴급한 처리를 요하는 사항일 때에는 이를 지체 없이 주무부서에 연락하거나 학교장에게 보고하고 필요한 조치를 하여야 한다.\n\n\n 제9조(당직근무자의 긴급사태 시 임무)\n\n①당직근무자는 학교에 화재가 발생한 때에는 지체 없이 다음 각 호의 조치를 하여야 한다.\n\n1. 관할 소방관서에의 연락\n\n2. 학교 내의 화재경보\n\n3. 자체 소화시설에 의한 진화작업\n\n②당직근무자는 외부침입자 등이 있을 때에는 지체 없이 다음 각 호의 조치를 하여야 한다.\n\n1. 관할 경찰서에의 연락\n\n2. 중요시설의 경비강화\n\n③당직근무자는 제1항 및 제2항의 경우와 기타 긴급한 사태가 발생한 경우에는 그 상황에 따라 학교장이나 상급기관의 당직근무자 또는 당직감독자에게 지체 없이 이를 보고하고, 그의 지시를 받아 필요한 조치를 한다. 다만, 특히 긴급을 요하여 상급기관 당직근무자 등의 지시를 기다릴 시간적 여유가 없을 때에는 긴급사태발생 보고와 함께 필요한 조치를 한 후 지체 없이 그 경과를 보고하여야 한다.\n\n④당직근무자는 각 기관의 장이 당직실에 비치하는 당직근무자의 긴급사태 시 행동요령을 숙지하여야 한다.\n\n\n 제10조(당직실의 비품)\n\n①당직실에는 다음 각 호의 서류 및 물품을 비치하여야 한다.\n\n1. 당직근무일지\n\n2. 기관 간 비상연락 체계도\n\n3. 직원 비상소집대장\n\n4. 향토예비군 비상소집대장\n\n5. 민방위대원 비상소집대장\n\n6. 관계기관의 당직실 전화번호부\n\n7. 비상열쇠 보관함(안전지출 및 파기계획)\n\n8. OO학교 당직근무 규정\n\n9. 기타 당직근무에 필요한 물품\n\n②제1항제1호의 당직근무일지는 학교의 특수성에 따라 학교장이 그 서식의 내용을 변경하여 사용할 수 있다.\n\n③제1항제3호 내지 제5호의 각 소집대장에는 전화․도보․교통수단 등의 연락방법이 2가지이상 기재되어야 한다.\n\n\n 제11조(기관의 당직감독) 학교장은 당직업무를 지휘․감독하는 당직감독관이 된다.\n\n\n 제12조(당직감독보좌관)\n\n①당직감독관을 보좌하기 위하여 보좌관을 둘 수 있다.\n\n②제1항의 보좌관을 두는 경우 행정실장이 되고, 행정실장이 없을 경우에는 학교장이 별도로 지정한다.\n\n\n 제13조(당직감독의 임무)\n\n①당직감독관은 학교의 당직근무자를 지휘․감독하고 다음 각 호의 사항을 점검한다.\n\n1. 당직근무자의 준수사항 및 당직임무의 이행여부\n\n2. 당직근무상황\n\n②제13조의 긴급사태가 발생한 때에는 당직감독관은 그 상황에 따라 지체 없이 이를 상급기관의 당직감독관에게 보고하고 그 지시를 받아 필요한 조치를 취하거나 기관별 당직근무자를 지휘하여 필요한 조치를 취한 후 당직 총감독관에게 보고하여야 한다.\n\n제14조(당직근무상태의 점검) 당직감독관은 학교의 당직근무자의 근무상태를 순찰 또는 전화 등에 의한 방법으로 확인․점검하여야 하며, 시각, 방법, 횟수는 기관의 장이 따로 정한다.\n\n제15조(당직근무태만자 등에 대한 조치) 당직감독관은 당직근무자의 규칙 위반사항을 발견한 때에는 이를 상급기관의 당직감독관에게 보고하여야 한다.\n\n제16조(비상근무의 목적) 비상근무는 비상사태 하에서 업무수행의 효율화를 도모하기 위하여 발령한다.\n\n\n 제17조(비상근무의 종류) 비상근무는 그 상황에 따라 다음과 같이 구분하여 발령한다.\n\n1. 비상근무 제1호: 전시, 사변 또는 이에 준하는 비상사태가 발생하였거나 발생이 임박하여 긴장이 최고조에 이른 경우\n\n2. 비상근무 제2호: 전시, 사변 또는 이에 준하는 비상사태와 관련된 긴장이 고조된 경우나 천재지변, 그 밖에 이에 준하는 사유로 사회불안이 조성되고 사회질서가 교란될 우려가 있는 경우\n\n3. 비상근무 제3호: 다음 각 목의 어느 하나에 해당하는 경우\n\n가. 전시, 사변 또는 이에 준하는 비상사태와 관련된 징후가 현저히 증가된 경우\n\n나. 적의 국지(局地)도발이 있는 경우로서 비상근무 제1호 또는 비상근무 제2호의 발령 단계에 이르지 않은 경우\n\n다. 천재지변, 그 밖에 이에 준하는 사유로 긴급한 대응이 필요하다고 판단되는 경우\n\n4. 비상근무 제4호: 제1호부터 제3호까지에서 규정된 경우 외에 위기상황에 신속하게 대응할 필요가 있거나 재해․재난, 그 밖에 긴급 상황 발생 등으로 비상근무가 필요하다고 인정되는 경우\n\n제18조(발령 및 해제) ①비상근무의 발령은 교육감이 교육부장관의 명을 받아 도내 전역 또는 일정지역을 지정하여 비상근무발령서에 의하여 발령하되, 이를 신속히 학교장에게 통보하여 비상근무에 임하도록 하여야 한다. 해제의 경우에도 또한 같다\n\n②교육감은 필요하다고 인정할 때에는 교육부장관의 승인을 얻어 소속직원에 대하여 비상근무를 발령할 수 있다. 다만, 특별히 긴급을 요하는 경우에는 비상근무를 발령하고 사후에 승인을 얻을 수 있다.\n\n제19조(비상근무의 요령) ①비상근무의 발령 중에는 부득이한 경우를 제외하고는 출장을 억제하고 소속직원의 소재를 항상 파악하여야 하며, 비상근무의 종류별로 다음 기준에 따라 휴가를 제한하고 휴일과 야간에는 소속직원을 비상근무하도록 하여야 한다.\n\n1. 비상근무 제1호가 발령된 때에는 연가를 중지하고, 소속직원의 3분의 1이상이 비상근무한다.\n\n2. 비상근무 제2호가 발령된 때에는 연가를 중지하고, 소속직원의 5분의 1이상이 비상근무한다.\n\n3. 비상근무 제3호가 발령된 때에는 부득이한 경우를 제외하고는 연가를 억제하고, 소속직원의 10분의 1이상이 비상근무한다.\n\n4. 비상근무 제4호가 발령된 때에는 부득이한 경우를 제외하고는 연가를 억제하고, 소속기관장이 정하는 바에 따라 비상근무한다.\n\n②학교장은 비상근무인원이 일부 부서 또는 일부 직급에 편중되지 아니하도록 부서별 인원․직급․업무의 성질 및 학교의 특수성 등을 감안하여 비상근무를 함으로써 비상근무기간 중 업무수행의 계속성이 유지되고 비상근무의 목적이 달성될 수 있도록 하여야 한다. 이 경우 비상근무인원에는 문서보관자․통신요원 등 사무보조에 필요한 인원이 포함되도록 하여야 한다.\n\n제20조(비상소집)①정상근무시간이 아닌 때에 제18조제1항 또는 제2항에 의한 비상근무가 발령된 경우에는 당직근무자는 지체 없이 학교장에게 이를 보고하고 학교의 전 직원이 비상소집 되도록 연락하여야 한다. 다만, 비상근무 제3호가 발령된 경우에는 발령자 또는 학교장의 명령의 따라 필요한 해당인원이 비상소집이 되도록 하여야 한다.\n\n②학교장 또는 당직근무자는 비상소집결과를 비상소집결과보고서에 의하여 상급기관의 당직근무자 또는 당직감독관에게 보고하여야 한다.\n\n제21조(비상근무기간중의 당직) ①각 기관 모두가 비상근무중일 때에는 학교의 당직근무를 중지 한다.\n\n②당직근무자가 당직근무중 비상근무가 발령되어 제1항의 규정에 의하여 당직근무를 중지할 때에는 당직 주무부서에 당직근무일지 등을 인계하여야 한다.\n\n③당직명령자는 정상근무시간 외에 비상근무가 해제된 때에는 지체 없이 당직근무를 하도록 조치하여야 한다.\n\n제22조(연습상황의 부여금지 등) 비상근무기간 중에는 비상근무발령자의 지시 또는 승인 없이 연습상황을 부여하여서는 아니 된다.\n\n제23조(직원 연락체계의 유지) ①교직원은 근무시간이 아닌 때에는 항상 소재파악이 가능하도록 연락체계를 유지하여야 한다.\n\n②교직원은 주소․전화번호 등 연락체계의 유지를 위하여 필요한 사항의 변경이 있는 때에는 이를 즉시 학교장에게 신고하여야 한다.\n\n③학교장은 소속공무원에 대한 자체 비상연락체계 점검 등 교육훈련목적상 필요하다고 인정되는 경우에 비상소집훈련을 할 수 있다.\n\n제24조(필수요원의 지정) ①학교장은 정상근무시간이 아닌 때에 긴급사태가 발생할 경우에 대비하여 소속직원 중 일부를 미리 필수요원으로 지정하고, 긴급사태 발생 시 신속히 필요한 조치를 하도록 하여야 한다.\n\n②제1항의 필수요원은 비상소집 시 1시간 이내에 응소 가능한 자를 우선적으로 지정하되, 문서보관자․통신요원 등 사무보조에 필요한 인원이 포함되도록 하여야 한다.\n\n제25조(직원비상소집대장의 정비․보완) ①학교장은 제20조제2항의 규정에 의한 신고를 받은 때에는 제10조제1항제3호에 규정된 직원비상소집대장을 즉시 정비․보완하여야 하며, 월 1회 이상 이를 점검하여야 한다.\n\n②학교장은 복무 또는 비상대비업무를 담당하는 소속공무원 중에서 직원연락체계의 유지 및 직원비상소집대장의 정비․보완을 위한 책임자 및 보조자 각 1인을 지정하여야 한다.\n\n부 칙\n\n이 규정은 20○○년 월 일부터 시행한다.\n\n\n!image\n\n\n!image","sectionId":"c04-w06"},{"id":"예시2","title":"당직 위탁 운영 계약서(예시)","content":"[예시2]\n\n 당직 위탁 운영 계약서(예시) \n\nOOOO학교 당직의 위탁 운영에 대한 계약을 체결함에 있어서 OOOO학교장을 “학교장”이라 칭하고, (주) OOOO ○○○ 대표를 “회사명”이라 칭하여 아래와 같이 계약을 체결한다.\n\n\n 제1장 총칙\n\n제1조 (목적) 본 계약은 “학교장”이 “회사명”에게 위탁한 경비대상에 대하여 “회사명” 이 제공한 경비원 (“회사명”이 “학교장”에게 제공하는 당직근무자를 말한다. 이하 같다)이 방범, 방호, 방화 등의 당직업무를 수행함으로써 “학교장” 의 인명과 재산의 손괴를 방지함을 그 목적으로 한다.\n\n제2조 (경비대상) “학교장”이 “회사명”에게 위탁하는 경비대상이라 함은 “학교장”의 인명과 시설 및 물품 등을 말하며 그 외 “학교장”이 지정한 대상으로 한다.\n\n제3조 (계약기간) 본 계약의 계약기간은 20○○년 3월 1일 16:30부터 20○○년 03월 1일 08:30까지로 하며 계약기간 종료 후 본 계약의 효력은 자동으로 소멸한다.\n\n제4조 (권리, 의무 양도의 금지) “학교장”과 “회사명”은 사전 서면동의 없이 본 계약의 권리와 의무의 일부 또는 전부를 제3자에게 양도하거나 본 계약의 목적 외 용도로 제공할 수 없다.\n\n\n 제2장 경비원과 경비근무\n\n제5조 (경비원) “회사명”이 “학교장”에게 제공하는 경비원은 경비업법 제7조의 결격 사유에 해당되지 아니하는 자로써 신체가 건강하고 사상이 건전하며 경비업법 시행령 제24조의 규정에 따라 교육을 이수한 자이어야 한다.\n\n\n 제6조 (근무시간) 1. 경비원의 근무시간은 다음의 각 호와 같다.\n\n가. 평 일: 16:30\\~익일 08:30 (16시간)\n\n나. 토요일, 공휴일: 08:30\\~익일 08:30 (단, “학교장”이 정한 임시 공휴일을 포함)\n\n\n 제7조 (경비원의 임무) 경비원의 임무 및 책임은 다음의 각 호와 같다.\n\n1.『전북특별자치도교육감 소속공무원의 당직 및 비상근무 규칙』상의 당직근무자의 임무 및 책임(긴급․비상사태 시 당직근무자의 임무 및 책임을 포함한다).\n\n2. 당직근무 중 “학교장”의 시설물에 대한 관리.\n\n3. 무인전자경비장치의 운영 및 교문 등 출입문의 개․폐\n\n4. 기타 당직의 수행을 위해 “학교장”과 “회사명”이 합의하에 정한 임무 및 책임.\n\n\n 제8조 (경비원의 준수사항) 경비원이 지켜야 할 준수사항은 다음의 각 호와 같다.\n\n1. 근무 중 근무지 이탈의 금지.\n\n2. 근무자로서의 품위를 손상하거나 당직근무에 지장이 있는 음주․도박․오락 행위 등의 금지.\n\n3. 규정된 복장의 착용 및 당직근무 표찰의 패용.\n\n4. 근무 중 알게된 “학교장”의 비밀을 누설하거나 타인의 이용에 제공하는 등 부당한 목적으로의 사용 금지\n\n5. 기타 당직근무의 수행을 위해 “학교장”과 “회사명”이 합의하에 정한 준수사항.\n\n제9조 (경비원의 교육) “회사명”은 경비원에게 경비업법 시행령 제24조 및 경비업법 시행규칙 제14조 및 제15조의 규정에 의거 15시간 이상의 신임교육과 매월 4시간 이상의 직무교육을 실시하여야 한다.\n\n제10조 (경비원의 복장 및 장구) “회사명”은 경비원에게 당직업무의 수행에 필요한 경비업법 시행규칙 제11조 및 제12조의 규정에 적합한 복장과 경적․경봉․분사기 등의 경비장구를 착용하게 하여야 하며 이에 소요되는 일체의 제반비용은 “회사명”의 부담으로 한다.\n\n\n 제3장 용역료 및 손해배상\n\n제11조 (월 용역료) “학교장”이 “회사명”에게 지급하는 월 용역료는 부가가치세를 포함한 1,300,000원으로 한다. 단, 1개월 미만의 용역료에 대해서는 일할계산하되, 근무일수의 산정은 일직과 숙직을 각각 1일로 본다.\n\n제12조 (용역료의 지급) “회사명”은 매월 20일까지 용역료를 “학교장”에게 청구하고 “학교장”은 “회사명”의 청구일로부터 10일 이내에 지로 또는 “회사명”의 계좌를 통하여 용역료를 지급한다.\n\n제13조 (용역료의 조정) 경제상황의 변화, 물가의 변동 및 기타 사유로 인하여 용역료의 조정사유가 발생한 경우 “회사명”과 “학교장”의 합의에 따라 계약상의 용역료를 조정할 수 있다.\n\n제14조 (손해배상) “회사명”은 “회사명” 또는 경비원이 업무수행 중 고의 또는 과실로 “학교장”에게 발생하는 손해를 방지하지 못한 경우와 제3자에게 손해를 입힌 경우 그 손해를 배상하여야 한다.\n\n제15조 (손해배상보험의 가입) “회사명”은 제14조의 손해배상을 위하여 “학교장” 등을 수혜자로 한 손해배상보험을 가입하고 보험가입증명서를 “학교장” 에게 제출하여야 한다.\n\n제16조 (손해배상보험의 가입금액) 제15조에 의한 손해배상보험의 가입금액은 최하대인 배상 1인당 이천만 원(10인 한도 2억원), 대물배상 1사고당 3억 원으로 한다.\n\n\n 제4장 계약의 해지\n\n제17조 (계약의 해지) “학교장”은 다음 각 호의 사유가 발생한 경우 구체적인 해지사유를 “회사명”에게 서면 통보함으로써 본 계약을 일방적으로 해지할 수 있다.\n\n1. “회사명”이 “회사명”의 폐업․휴업 등으로 “학교장”에게 더 이상 경비용역을 제공할 수 없는 경우.\n\n2. “회사명”이 경비업법 제12조 및 경비업법 시행령 제22조의 규정에 의하여 허가취소․영업정지 등 행정처분을 받음으로써 “학교장”에게 더 이상 경비용역을 제공할 수 없는 경우.\n\n3. “회사명” 및 경비원의 불성실, 근무태만, 경비업무 수행에 관한 시정 지시의 불이행 등으로 당직업무 수행에 지장을 초래한 경우.\n\n4. “회사명”의 계약조건 위반으로 인하여 계약의 본래 목적을 달성할 수 없다고 “학교장”이 판단한 경우.\n\n제18조 (계약보증금) 계약이행의 보증을 위하여 “회사명”은 “학교장”에게 계약기간 중 전체 용역료의 100분의 10에 해당하는 금액을 계약보증금으로 납부하여야 한다. 단, 계약보증금은 현금 또는 보증보험증권 및 이에 갈음할 수 있는 보증서로 납부할 수 있다.\n\n\n 제5장 기 타\n\n제19조 (경비계획서의 작성) “회사명”은 본 계약서에서 정한 사항 이외에 대하여 “학교장”의 요청 또는 기타 필요에 따라 별도의 경비계획서를 작성할 수 있다. 단, 경비계획서는 “학교장”의 사전 승인을 받아야 한다.\n\n제20조 (관할법원) 이 계약에 관한 합의․소송 등의 관할은 “학교장”의 주소지 관할 법원으로 한다.\n\n제21조 (기타) 이 계약서에 정하지 아니한 사항은 『지방자치단체를 당사자로 하는 계약에 관한 법률』『지방자치단체를 당사자로 하는 계약에 관한 법률 시행령』『지방자치단체를 당사자로 하는 계약에 관한 법률 시행규칙』의 규정을 적용한다.\n\n동 계약을 증명하기 위하여 본 계약서 2부를 작성하여 상호 인감 날인 후 각각 1부씩 보관한다.\n\n20○○년 월 일\n\n“학교장” 학교명: oooo학교\n\n사업자 등록번호: ooo -oo -oooo\n\n주소: 전북특별자치도 시 로 ooo( 면 로 ooo)\n\n대표자: oooo학교장 OOO( 인 )\n\n“회사명” 상호명: (주)OOO\n\n사업자등록번호: OOO-OO-OOOO\n\n주소: 전북특별자치도 시 로 ooo( 면 로 ooo)\n\n대표자: OOO ( 인 )\n\n\n!image\n\n\n!image","sectionId":"c04-w06"},{"id":"예시3","title":"노동(근로) 계약서(예시)","content":"[예시3]\n\n 노동(근로) 계약서(예시) \n\n 사용자 과 노동자 는 다음과 같이 노동계약을 체결하고 이를 성실히 이행할 것을 약정한다.\n\n 1. 직 종 명: \n\n 2. 노동자의 인적사항 \n\n \n 성 명 성 별 연 령 생년월일 주 소 \n 0 0 0 0 전북특별자치도 00시 00로 \n 연락처 최초채용일 근무기관 계약형태 \n 자 택 휴대폰 063-○○○-○○○○ 010-○○○○-○○○○ 0000.00.00 (무기계약/기간제/촉탁직) \n \n\n 3. 계약기간 : 년 월 일부터 년 월 일까지로 한다.\n\n※ 무기계약직의 경우: 정년 또는 사업 종료 시까지로 한다.\n\n※ 촉탁직, 기간제노동자의 경우 노동계약기간 작성\n\n※ 휴직, 휴가 등의 사유로 대체 채용된 교육공무직의 경우 원 노동자가 복직할 경우 계약기간 중이라도 계약이 종료됨\n\n 4. 수습기간 \n\n◦ 수습기간은 채용일로부터 3개월까지로 한다.\n\n◦ 수습기간 중에 있는 노동자의 근무태도 및 근무수행 능력이 불량하거나, 노동자가 계속노동이 부적격하다고 인정되는 경우 노동계약을 해지할 수 있다.\n\n 5. 근무장소 및 담당업무 \n\n◦ 근무장소: 사용자가 지정하는 장소\n\n◦ 담당업무: 해당 직종 사업부서 및 운영기관의 장이 분장하는 업무\n\n 6. 근무일 및 노동시간 \n\n◦ 노동형태: (상시근무자 또는 방학 중 비상시 근무자) 중 기재\n\n※ 방학 중 비근무하는 노동자의 소정 근무일에 관하여는 연간 노동계획서에 따름\n\n◦ 근무일 및 노동시간\n\n- 근무일: 월요일\\~금요일\n\n- 노동시간: 1주 40시간, 1일 8시간((예) 08:30\\~16:30) 다만, 사용자가 업무상 필요에 의해 노동시간을 조정하는 경우 이에 따른다.\n※ 전일제가 아닌 단시간 노동자의 경우 변경 필요.\n\n◦ 휴게: 휴게시간은「근로기준법」제54조 및「전북특별자치도교육감 소속 교육공무직원 관리규정」에 따라 부여한다.\n\n 7. 보수 \n\n◦ 지급형태: 월급제(또는 일급제, 시급제)\n\n◦ 지급금액:\n\n 기 간 통상임금 산정노동시간 기본급 비 고 \n --- --- --- --- \n 209시간 (전일제 노동자가 아닌 경우 변경 요망) 월 000원 (또는 일급 000원, 시급 000원) 각종 수당은 도교육청 처우개선 관련 지침에 따름 \n\n◦ 보수지급일: 매월 일. 휴일인 경우 그 전일 지급\n\n◦ 보수지급방법: 노동자 통장 계좌입금\n\n 8. 휴일 및 휴가 등 :「근로기준법」및「전북특별자치도교육감 소속 교육공무직원 관리규정」에 따라 부여한다.\n\n 9. 근무시간, 근무장소, 보수, 담당업무 등의 노동조건: 기관의 업무량, 예산 사정 등에 따라 변경될 수 있다.\n\n 10. 기타: 본 계약서에 명시되지 아니한 사항은「근로기준법」등 노동관계법령과 「전북특별자치도교육감 소속 교육공무직원 관리규정」에 따른다.\n\n 위 계약서 2부를 작성하여 사용자와 노동자가 각각 1부씩 보관한다. \n\n※ 1부를 교부 받았음을 확인함 노동자 ○ ○ ○ (서명/인)\n\n붙임 연간 노동계획서 1부.\n (방학 중 노동하지 않는 노동자가 방학 중 노동하는 경우에는 반드시 작성)\n\n 년 월 일 \n\n 사 용 자: (교육장 또는 학교장) (직인) \n\n 노 동 자: (서명/인) \n\n 서 약 서 \n\n본인은 〇〇〇직종으로 채용됨에 따라 다음 사항을 준수할 것을 서약합니다.\n\n1. 근무 중 알게 된 모든 기밀사항은 계약기간중은 물론, 계약만료 후에도 외부에 일체 누설하지 않는다.\n\n2. 직무 관련 법령을 준수하고 관리자의 직무상 명령에 따른다.\n\n3. 출 ․ 퇴근시간 및 소속 기관의 제반 근무수칙을 엄수한다.\n\n4. 소속 기관의 명예와 신용을 손상하거나 업무관련 자료를 유출하는 일이 없도록 한다.\n\n5. 업무 수행 중 특별한 문제점이 발생될 시에는 즉시 관리자에게 보고하고 업무지시를 받는다.\n\n이상과 같이 성실한 자세로 근무에 임할 것을 서약합니다.\n\n년월일\n\n서약자: ○○○ (서명/인)\n\n ○○초등학교장 귀하 \n\n[별표1]\n\n 당직근무표찰 (제7조제2항 관련) \n\n \n \n \n ① ② \n 4cm \n \n ------------------------8cm --------------------- \n ≪주 의≫ 1. 위의 ①, ②란에는 다음 사항을 표시한다 ① 당직기관명을 기재함 ② 당직 정․부책임자 등을 기재함 2. 글자의 크기는 다음과 같다 \n 구분 글자의 크기 글자의 종류 글자의 색체 \n ① 20포인트 고딕체 검정색 \n ② 26포인트 고딕체 검정색 \n 3. 재료는 두께 0.2㎝의 백색 아크릴을 사용한다 4. 뒷면에 옷핀을 달아 패용이 가능하도록 한다. \n \n\n\n!image\n\n\n!image","sectionId":"c04-w06"}],"faqs":[{"id":"faq-학교행정업무길라잡이웹판-1-1","category":"휴가","number":1,"question":"종무식이 있는 날의 퇴근시간","answer":"･ 종무식은 한해의 마무리를 기념하는 행사에 불과하고 근무시간의 종료를 의미하는 것은 아니므로 종무식이 있는 날에도 국가공무원복무규정에 규정된 근무시간을 준수하여야 함.\n【관련 규정】지방공무원복무규정 제2조(근무시간 등)\n【관련 부서】총무과"},{"id":"faq-학교행정업무길라잡이웹판-2-2","category":"휴가","number":2,"question":"불법행위 목적의 외출신청에 대한 처리","answer":"･ 불법집회를 지원 또는 참가할 목적으로 외출 등을 신청한 경우 허가권자는\n동 외출 등의 불법성을 고려하여 외출을 허가하지 아니할 수 있음\n【관련 부서】총무과"},{"id":"faq-학교행정업무길라잡이웹판-3-3","category":"휴가","number":3,"question":"결근일과 결근일 사이 공휴일의 근무상황 처리","answer":"․ 결근이 공휴일을 전후하여 계속되더라도 공휴일은 출근의무가 없는 날이므로 근무상황부에 결근일과 결근일 사이의 공휴일을 결근으로 처리하지 않음.\n※ 공휴일을 결근으로 처리하는 경우도 있음에 유의\n봉급감액의 경우 결근일과 결근일 사이의 공휴일도 결근일수로 봄\n【관련 규정】공무원보수등의 업무지침\n【관련 부서】총무과, 재무과"},{"id":"faq-당직근무-1-1","category":"당직 및 비상근무","number":1,"question":"당직근무 후 휴무","answer":"․ 공무원이 숙직근무 후 익일 오전 또는 오후 중 하나를 선택하여 휴무할 수 있으며, 근무상황부의 종별란에「당직휴무」라고 기재함.\n․ 다만, 일직근무자는 익일 휴무를 부여받지 못함.\n【관련 규정】전북특별자치도교육감소속 공무원 당직 및 비상근무규칙 제4조\n【관련 부서】총무과"},{"id":"faq-당직근무-2-2","category":"휴가","number":2,"question":"재택당직근무자의 퇴청 및 책임 범위","answer":"․ 근무시간 종료 이후 사무실 대기를 마친 재택당직근무자는 잔무처리를 하고 있는 잔류직원이 사무실에 남아있더라도 무인경보장치 등 필요한 조치를 취하고 퇴청하여 재택당직근무에 임할 수 있음.\n․ 재택당직기관에서 당직근무 시간 중 문제발생에 따른 재택당직근무자와 최종 퇴청자의 책임의 소재는 1차적으로 최종 퇴청자에게 있고, 2차적으로는 재택당직근무자 등에게 있으나, 개별사안에 따라 제반 상황 등을 종합적으로 고려하여 책임소재를 밝히는 것이 타당함.\n【관련 규정】국가공무원 복무․징계 관련 예규, 국가공무원복무규정 제5조(당직및비상근무)\n【관련 부서】총무과"},{"id":"faq-당직근무-3-3","category":"당직 및 비상근무","number":3,"question":"재택당직근무자의 당직비","answer":"․ 재택당직근무자에 대한 당직비는 당직자가 근무시간 종료시부터 계속하여 사무실에서 3시간 이상 대기근무한 경우에만 지급이 가능함.\n․ 근무시간 종료 후 2시간 대기근무하고 다음날 1시간 조기출근한 경우에는 당직비 지급이 불가함.\n【관련 규정】전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙\n【관련 부서】총무과"},{"id":"faq-당직근무-4-4","category":"당직 및 비상근무","number":4,"question":"당직면제와 재택당직","answer":"․ 당직면제 조건을 충족하여 당직근무를 하지 않는 기관의 경우 별도의『재택 당직』을 하지 않아도 됨.\n【관련 규정】전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙 제11조\n【관련 부서】총무과"},{"id":"faq-당직근무-5-5","category":"휴가","number":5,"question":"재택당직근무자의 시간외근무","answer":"․ 재택당직근무자는 일정시간의 사무실 대기와 퇴청 이후에도 당직근무를 성실히 수행할 의무가 있으므로 재택당직근무자에 대하여 시간외근무를 명할 수 없음.\n【관련 규정】지방공무원 복무규정\n【관련 부서】총무과"},{"id":"faq-당직근무-6-6","category":"당직 및 비상근무","number":6,"question":"정직기간 중 당직근무 가능 여부","answer":"․ 정직기간 중에는 공무원 신분은 보유하나 직무에 종사할 수 없으므로 정직기간 중의 공무원은 직무수행의 일종인 당직근무를 할 수 없음.\n【관련 규정】지방공무원 복무규정\n【관련 부서】총무과"},{"id":"faq-당직근무-7-7","category":"당직 및 비상근무","number":7,"question":"당직실의 향토예비군소집명부 및 민방위대원소집명부 비치","answer":"․ 향토예비군소집명부 및 민방위대원소집명부는 직장예비군 및 직장민방위대 편성된 기관에만 비치함.\n․ 통합편성 직장민방위대는 민방위사태에 공동으로 대처하기 위한 것인 점을 감안, 통합직장민방위대에 소속된 모든 기관에서는 민방위대원명부를 비치하여야 함.\n【관련 규정】전북특별자치도교육감 소속 공무원 당직 및 비상근무 규칙\n【관련 부서】총무과"},{"id":"faq-출장명령-1-1","category":"초과근무","number":1,"question":"근무지내 출장자의 초과근무 인정","answer":"․ 근무지내 출장명령을 받은 공무원은 출장업무를 마치고 사무실로 귀청하여 계속 근무하는 경우에는 초과근무를 인정할 수 있음.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원), 공무원보수 등의 업무지침\n【관련 부서】총무과, 재무과"},{"id":"faq-출장명령-2-2","category":"당직 및 비상근무","number":2,"question":"소속직원의 경조사에 기관대표로 참석","answer":"․ 소속직원의 경조사에 기관대표로 참석할 경우 출장조치와 여비지급은 가능하나, 최소한의 인원에 한함.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원)\n【관련 부서】총무과"},{"id":"faq-출장명령-3-3","category":"휴가","number":3,"question":"출장명령과 출장여비 지급","answer":"․ 출장명령은 출장여비의 지급근거가 되는 것이나, 출장명령이 있다고 하여 반드시 출장여비를 지급하는 것은 아님. 직무와 관련하여 공무원교육원에 출강하여 강사료를 받은 경우 출장여비 지급없이 출장으로 처리함.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원), 공무원보수 등의 업무지침\n【관련 부서】총무과, 재무과"},{"id":"faq-출장명령-4-4","category":"휴가","number":4,"question":"근무지내 출장명령 및 출장여비 지급","answer":"․ 근무지내 출장을 마치고 귀청 후에 또다시 근무지내 출장명령은 가능하나, 공무원여비규정에 근무지내 4시간 이상 출장은 20,000원, 4시간 미만 출장은 10,000원을 지급하므로 20,000원을 초과하는 여비를 지급할 수 없음.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원), 공무원보수 등의 업무지침\n【관련 부서】총무과, 재무과"},{"id":"faq-출장명령-5-5","category":"휴가","number":5,"question":"근무시간 이후 근무지내 출장용무가 발생한 경우","answer":"․ 근무시간 중 근무지내 출장명령과 이에 따른 여비를 지급 받고 귀청 후 근무시간 이후 근무지내 출장용무가 발생한 경우에는 시간외근무명령을 하고 이에 따른 수당을 지급함.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원), 공무원보수 등의 업무지침\n【관련 부서】총무과, 재무과"},{"id":"faq-출장명령-6-6","category":"휴가","number":6,"question":"민간단체 주관 행사 참석시 복무관리","answer":"․ 보이스카웃, 사회복지법인 등 민간단체 행사에 초청되어 참석하는 경우 당해 공무원의 업무와 관련성이 있고 소속기관의 대표자격으로 참석할 경우에는 출장조치가 가능하나, 개인자격으로 참석할 경우에는 연가로 처리해야 함.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-출장명령-7-7","category":"휴가","number":7,"question":"외부 출강 시 출장처리 등","answer":"․ 민간기관 또는 산하기관에 출강할 경우 강의가 직무수행과 관련이 있는 경우에는 출장조치가 가능하나, 직무수행과 무관한 출강의 경우에는 연가를 사용해야 함.\n․ 출장조치가 가능한 출강한 경우에도 강의를 요청한 기관에서 실비를 지급할 경우에는 출장여비를 지급할 수 없음.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원), 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-출장명령-8-8","category":"휴가","number":8,"question":"근무시간 중의 주간대학원 수강","answer":"․ 공무원이 주간대학원에 수학하는 문제는 소속기관이 관여할 사항이 아니며, 근무시간 중 동 대학원의 강의를 듣기 위한 출장처리도 불가함.\n․ 다만, 수강을 위하여 소속기관장 또는 부서장의 허가를 얻어 연가를 사용할 수 있으나, 본인의 연가일수를 초과한 경우에는 결근으로 처리함.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-출장명령-9-9","category":"휴가","number":9,"question":"국외에서 훈련 중인 공무원이 일시 귀국하는 경우","answer":"･ 국외에서 위탁교육훈련을 받는 공무원이 일시 귀국하고자 하는 때에는 귀국사유 등을 명시하여 소속 중앙행정기관의 장을 거쳐 훈련주관부서(중앙행정기관의 장 또는 중앙인사위원회)의 승인을 얻어야 함.\n【관련 규정】공무원 인재개발법 시행령 제40조(일시귀국)제1항\n【관련 부서】총무과"},{"id":"faq-출장명령-10-10","category":"출장","number":10,"question":"공무원직장협의회의 활동과 출장","answer":"․ 출장소 또는 지소에 근무하는 공무원직장협의회 회원이 직장협의회가 설립된 본청 기관장과의 정기적인 협의에 참석하는 경우에는 출장이 가능하지만,\n․ 공무원직장협의회에서 개최하는 운영회의에 참석하는 경우에는근무시간 중 협의회 활동 제한규정에 저촉되므로 출장으로 처리할 수 없음.\n【관련 규정】지방공무원 복무규정 제4조2(출장공무원)\n【관련 부서】총무과"},{"id":"faq-출장명령-11-11","category":"휴가","number":11,"question":"공휴일을 이용하여 공무외의 국외여행을 하는 경우","answer":"․ 공휴일에 공무외의 국외여행을 하는 경우에는 근무상황부에 기재하거나 소속기관에 신고할 의무는 없으나,\n․ 사전에 여행일정과 여행지 등을 비상연락담당자에게 통보하여 긴급 시 소재파악 및 비상연락이 될 수 있도록 비상연락체계가 유지되어야 함.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류), 전북특별자치도교육감 소속 지방공무원 복무 조례 제25조\n【관련 부서】총무과"},{"id":"faq-공무원의복장-1-1","category":"휴가","number":1,"question":"찢어진 청바지 착용","answer":"･ 공무원이 업무에 임함에 있어 국민에게 신뢰감을 심어주고 혐오감을 불러일으키지 않도록 하기 위해서는 단정한 용모를 갖추어야 하므로 삼가야 할 것임.\n【관련 규정】지방공무원 복무규정 제1조의3(복장 및 복제 등)\n【관련 부서】총무과"},{"id":"faq-공무원의복장-2-2","category":"휴가","number":2,"question":"공무원 벙거지모자와 귀걸이 착용","answer":"･ 공무원의 두발이나 장신구는 공무원으로서 그 품위를 유지할 수 있도록 단정해야 하며, 그 기준은 사회통념이나 관례에 따라야 할 것임.\n【관련 규정】지방공무원 복무규정 제1조의3(복장 및 복제 등)\n【관련 부서】총무과"},{"id":"faq-휴가-1-1","category":"휴가","number":1,"question":"재직기간과 휴가","answer":"․ 연가는 개인별 재직기간에 따라 정해진 사용가능일수의 범위 내에서만 사용할 수 있는 반면,\n․ 병가․공가․특별휴가는 모든 공무원이 재직기간에 관계없이 휴가사유가 동일하다면 동일한 휴가일수를 사용할 수 있음.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급), 제7조의6(공가), 제7조의7(특별휴가), 전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가)\n【관련 부서】총무과"},{"id":"faq-휴가-2-2","category":"휴가","number":2,"question":"휴가기간 중 전보발령","answer":"･ 휴가기간 중 전보된 경우 동 휴가는 전보발령일 전일까지 유효하고, 전보발령일 이후의 휴가는 새로운 허가권자에게 다시 허가를 받아야 함.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-휴가-3-3","category":"휴가","number":3,"question":"휴가일수 계산방법","answer":"･ 연가․병가․공가․특별휴가는 그 사유와 용도가 각각 다르고 별개의 휴가로서 휴가일수를 종류별로 따로 계산함.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-휴가-4-4","category":"휴가","number":4,"question":"휴가사유가 중복되는 경우","answer":"･ 같은 날 병가․공가․특별휴가 등 2개 이상 휴가사유가 중복되는 경우 본인이 선택하여 신청하는 하나의 휴가만을 허가함.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-휴가-5-5","category":"휴가","number":5,"question":"가족의 연락에 따른 휴가 허가","answer":"･ 휴가는 본인의 신청이 있는 경우에 허가하며, 공무원 본인의 연락 없이 가족의 연락만으로 휴가를 허가하는 것은 불가함.\n･ 다만, 갑작스런 병가나 특별휴가 등 불가피한 경우에는 가족이 연락하여 다른 공무원으로 하여금 휴가신청을 대행하게 할 수 있음.\n【관련 규정】지방공무원 복무규정 제6조(휴가의 종류)\n【관련 부서】총무과"},{"id":"faq-연가-1-1","category":"휴가","number":1,"question":"연가일수를 초과하여 출근하지 못한 경우","answer":"․ 부득이한 사정으로 본인의 연가가능일수를 초과하여 출근하지 못하게 된 경우에는 결근으로 처리됨.\n【관련 규정】공무원보수 등의 업무지침\n․ 당해 공무원의 연가일수를 초과한 결근일수 매 1일에 대해 봉급일액의 2/3를 감함\n․ “결근일수”는 당해 공무원의 결근일수(결근일과 결근일 사이에 있는 공휴일은 결근일수로 봄)가 당해 공무원의 연가일수를 초과한 경우 그 초과한 결근일수를 말함.\n【관련 부서】총무과"},{"id":"faq-연가-2-2","category":"휴가","number":2,"question":"연가일수를 초과한 외출 등 금지","answer":"․ 외출․조퇴․지참․반일연가는 연가일수를 초과하여 사용할 수 없음.\n※ 연가일수 공제 시 연간 외출 등의 잔여시간 8시간 미만을 계산하지 않는다고 하여 연가일수를 초과한 8시간 미만의 외출 등을 허용한 것은 아님.\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제26조(휴가기간의 초과)\n【관련 부서】총무과"},{"id":"faq-연가-3-3","category":"휴가","number":3,"question":"휴직․결근․정직․직위해제일수가 있는 경우의 연가 가산","answer":"․연가가산은 1년간 성실하게 근무한 공무원에 대한 인센티브이므로 휴직 ․ 결근 ․ 정직 ․ 직위해제일수가 있는 공무원은 병가 미활용 및 연가보상비 미수령 일수가 있더라도 연가 가산을 할 수 없음.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급)\n【관련 부서】총무과"},{"id":"faq-연가-4-4","category":"휴가","number":4,"question":"연가일수 산정 시 재직기간 계산방법","answer":"․ 연가일수를 산정할 때의 재직기간에는 공무원연금법 제23조 제1항, 제2항, 제3항에서 규정된 공무원, 군인, 사립학교교직원, 현역 및 하사관의 복무기간 등을 합산함.\n․ 다만 위 재직기간을 합산할 때에는 공무원연금법 제23조 제1항 규정의 년․ 월로 계산하는 것이 아니라 민법의 계산방법에 따라 년․월․일로 계산함.\n※ 현역 복무기간(2년 3월)과 공무원경력(2월 10일)이 있는 상태에서 2006. 7. 1. 임용되어 2006. 12. 31.까지 재직한 경우의 재직기간은 2년 11월 10일(2년 3월 + 2월 10일 + 6월)이고, 재직기간별 연가일수는 재직기간 2년 이상 3년 미만에 해당되므로 12일임.\n- 공무원의 재직기간은 임용일을 포함하고, 퇴직일은 제외하나 군 복무기간은 입대일과 전역일을 모두 포함.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급)\n【관련 부서】총무과"},{"id":"faq-연가-5-5","category":"휴가","number":5,"question":"연가일수에서 공제한 정직처분이 사면된 경우","answer":"․정직처분이 사면되었더라도 이미 처분받은 불이익을 소급하여 원상회복하는 것은 아니므로 사면일 이전의 정직처분은 유효하고 연가가산 할 수 없음.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급)\n【관련 부서】총무과"},{"id":"faq-연가-6-6","category":"휴가","number":6,"question":"공무상병가 사용자의 병가 미활용 사유로 연가가산 불가","answer":"․ 병가를 활용하지 않은 경우의 연가가산 ⇨ 일반병가는 물론 공무상병가도 없어야 함.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급)\n【관련 부서】총무과"},{"id":"faq-연가-7-7","category":"휴가","number":7,"question":"연가가산이 되지 않는 휴직의 의미","answer":"․ 전년도 휴직일수가 있어 연가가산을 할 수 없는 경우에서의 휴직이라 함은 일반 휴직뿐만 아니라 공무상질병 휴직이나 병역복무 휴직 등 모든 휴직을 의미함.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급)\n【관련 부서】총무과"},{"id":"faq-연가-8-8","category":"휴가","number":8,"question":"퇴직과 동시에 재임용된 공무원의 연가가산","answer":"․ 전년도 1월 1일부터 계속 근무하던 중 퇴직과 동시에 재임용된 경우에는 연가 가산을 할 수 있음.\n【관련 규정】지방공무원 복무규정 제7조(연가일수 및 연가보상비의 지급)\n【관련 부서】총무과"},{"id":"faq-병가-1-1","category":"휴가","number":1,"question":"2개 년도에 걸쳐 30일을 초과하는 병가","answer":"․ 2개 년도에 걸쳐 30일을 초과하는 병가의 경우에는 연도별로 구분하여 각각 30일 이상인 경우에만 공휴일과 토요일을 병가 일수에 산입함.\n【관련 규정】지방공무원 복무규정 제7조의8(휴가기간 중의 토요일 또는 공휴일)\n【관련 부서】총무과"},{"id":"faq-병가-3-2","category":"휴가","number":3,"question":"미용을 위한 성형수술의 병가 가능 여부","answer":"․ 미용을 위한 성형수술은 병가사유인 질병이나 부상으로 볼 수 없으므로 병가를 사용할 수 없으며, 필요한 경우에는 개인연가를 사용하여야 할 것임.\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가)\n【관련 부서】총무과"},{"id":"faq-병가-4-3","category":"휴가","number":4,"question":"병가와 연속된 연가","answer":"․ 7일간의 병가를 사용한 후 23일간의 연가를 사용함으로써 사실상 휴가기간이 30일 이상인 경우, 병가와 연가는 별개의 요건에 따라 운영되고 그 기간을 따로 계산하므로 각각 30일을 초과하지 않으므로 공휴일과 토요일을 산입하지 않고 계산함.\n【관련 규정】지방공무원 복무규정 제7조의8(휴가기간 중의 토요일 또는 공휴일)\n【관련 부서】총무과"},{"id":"faq-병가-5-4","category":"휴가","number":5,"question":"장기기증을 위한 병가 가능 여부","answer":"․장기기증으로 인한 수술이나 입원기간에 대하여는 병가를 사용할 수 있음.\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가)\n【관련 부서】총무과"},{"id":"faq-병가-6-5","category":"휴가","number":6,"question":"불임의 치료 및 라식수술을 위한 병가 가능 여부","answer":"․ 불임 및 라식수술의 경우 병가사유인 질병에 해당되므로 불임의 치료 및 라식 수술로 인하여 직무를 수행할 수 없는 경우에는 병가를 사용할 수 있음.\n- 불임치료의 경우 지방공무원 복무규정에따라 특별휴가를 사용할 수 있음.\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가), 제23조(특별휴가)\n【관련 부서】총무과"},{"id":"faq-병가-7-6","category":"휴가","number":7,"question":"질병이나 부상으로 60일을 초과하여 쉬고자 하는 경우","answer":"․ 일반병가는 연간 60일 범위 내에서만 가능하므로 60일을 초과하여 쉬고자 하는 경우에는 본인의 연가일수 범위 내에서 연가를 사용하여야 함.\n․ 그 이후에도 계속 질병치료 등으로 출근이 불가능한 경우에는 휴직을 해야 함.\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가)\n【관련 부서】총무과"},{"id":"faq-병가-8-7","category":"휴가","number":8,"question":"병가 사용 중 특별휴가 사유가 발생했을 경우","answer":"․ 병가 사용 중 경조사 등 특별휴가 사유가 발생한 경우 병가와 특별휴가는 별도로 사용이 가능하므로 본인의 신청에 따라 병가를 취소하고 특별휴가로 처리할 수 있음.\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가), 제23조(특별휴가)\n【관련 부서】총무과"},{"id":"faq-병가-9-8","category":"휴가","number":9,"question":"연도를 달리하는 경우의 일반병가 사용","answer":"․ 일반병가는 1년 단위로 60일을 사용할 수 있으므로 11월부터 12월 말일까지 병가 60일을 사용한 경우에도 다음해 1월 1일부터 병가 60일을 다시 사용할 수 있음.\n※ 연도를 달리하더라도 동일 사유 병가인 경우 최초 제출한 진단서로 갈음 가능\n【관련 규정】전북특별자치도교육감 소속 지방공무원 복무 조례 제21조(병가)\n【관련 부서】총무과"},{"id":"faq-공가-2-1","category":"휴가","number":2,"question":"업무수행에 필수적인 자격증 보수교육을 위한 공가 가능 여부","answer":"․ 공무수행에 필요한 자격증을 가지고 근무하는 공무원이 자격증의 효력유지를 위하여 보수교육을 받아야 할 경우 공가처리하고 보수교육을 받을 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-3-2","category":"휴가","number":3,"question":"자동차 안전교육 참석을 위한 공가 가능 여부","answer":"․ 개인적인 용도로 사용하기 위해 구입한 가스사용 자동차 운행을 위하여 법령에 의한 안전교육에 참석할 경우에는 공가를 사용할 수 없음.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-4-3","category":"휴가","number":4,"question":"구속된 경우의 공가 가능 여부","answer":"․ 공무원이 구속되어 출근을 할 수 없는 경우 기소 전 까지는 공가로 처리. 이는 유죄판결이 확정될 때까지는 무죄로 추정되는 헌법정신을 감안한 것임. 다만, 공가기간이 장기화되는 것은 바람직하지 않으므로 신속하게 직위해제 또는 징계 등의 조치를 하여야 할 것임.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-5-4","category":"휴가","number":5,"question":"자격증 취득 시험응시를 위한 공가 가능 여부","answer":"․ 공무원이 업무수행에 필요한 일반적인 자격증을 새로 취득하기 위하여 응시하고자 하는 때에는 연가를 사용하여야 함. 그러나 승진, 전직, 전보 등 임용의 전제가 되는 자격취득을 위한 시험에 응시하거나 그 면허교부를 받기 위한 경우는 공가 활용이 가능하다고 보며, 그 자격증이 임용요건으로 의무화되어 있는 경우 자격증의 효력을 유지하기 위하여 보수교육을 받아야 할 때에는 교육파견 절차에 따라 처리함이 타당한 것으로 판단됨.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-6-5","category":"휴가","number":6,"question":"군 입대예정자에 대한 입대 전 공가 가능 여부","answer":"․ 공무원이 군 입대 전에 며칠간의 휴가를 얻고자 할 경우 공가를 사용할 수 없음. 다만, 연가를 사용하는 것은 무방함.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-7-6","category":"휴가","number":7,"question":"한글날 등 각종 기념행사 참석을 위한 공가 가능 여부","answer":"․ 한글날 등 국가가 주관하는 각종 기념행사에 참석할 때에는 공가를 사용할 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-8-7","category":"휴가","number":8,"question":"징계․소청․행정소송의 당사자 등 공가처리","answer":"․ 징계․소청․행정소송 절차에 출석하는 업무담당 공무원은 출장으로 처리하고,\n․ 당사자 또는 참고인으로 출석하는 공무원에 대하여는 공가로 처리. 다만, 행정소송의 경우 그 내용이 공직신분과 무관한 민사에 관한 사항은 연가를 활용해야 함.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-공가-9-8","category":"휴가","number":9,"question":"지방자치단체장 보궐선거 투표참가를 위한 공가 가능 여부","answer":"․ 공직선거법에 의한 지방자치단체장 보궐선거 투표에 참여하는 공무원도 공가를 사용할 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의6(공가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-1-1","category":"휴가","number":1,"question":"입양된 공무원이 경조사휴가를 받을 수 있는 직계존속의 범위","answer":"․ 양부모와 친부모, 양조부모와 친조부모 모두 경조사 특별휴가를 얻을 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가), 전북특별자치도교육감 소속 지방공무원 복무 조례 제23조(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-2-2","category":"휴가","number":2,"question":"퇴근시간 이후에 발생한 경조사휴가 일수 계산 방법","answer":"․ 정규근무를 마치고 퇴근시간 이후에 상을 당한 경우에는 당일은 경조사 휴가 일수에서 제외하고, 그 다음날부터 경조사휴가 일수를 계산함.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-3-3","category":"휴가","number":3,"question":"경조사 특별휴가 발생 사유의 소명방법","answer":"․ 특별휴가를 신청할 경우 이를 소명할 수 있는 증빙자료(예: 결혼청첩장, 부고장 등)를 첨부하는 것이 원칙임. 그러나 특별휴가 사유가 객관적으로 명확한 경우에는 생략할 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-4-4","category":"휴가","number":4,"question":"특별휴가일수 가산대상인 원격지의 판단기준","answer":"․ 특별휴가일수 가산대상인 원격지의 개념을 획일적으로 규정하기는 곤란하며, 지역과 교통여건 등을 감안하여왕복소요일수를 가산하지 않으면 특별휴가 목적을 달성할 수 없다고 판단되는 경우허가권자의 판단에 의하여 가산할 수 있음. 예를 들어, 서울에서 근무하는 공무원이 경조사에 참석하기 위해 육로와 배를 이용하기 위해 장시간 소요되는 전남 흑산도까지 가야 할 처지라면 왕복소요일수를 추가해 줄 수 있을 것임.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-5-5","category":"휴가","number":5,"question":"사실혼 관계인 배우자의 경조사휴가 가능 여부","answer":"․ 사실혼 관계인 배우자의 경조사에도 경조사휴가를 얻을 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-6-6","category":"휴가","number":6,"question":"배우자의 출산 시 경조사휴가 사용 시기","answer":"․ 배우자의 출산 시 사유 발생일로부터 120일 이내의 범위에서 20일의 경조사휴가를 3회에 한하여 분할 사용 가능, 한번에 둘 이상의 자녀를 출산한 경우에는 25일의 경조사휴가를 그 사유 발생일로부터 150일 이내의 범위에서 5회에 한하여 분할 사용 가능함.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-7-7","category":"휴가","number":7,"question":"미혼인 여성의 출산휴가","answer":"․ 출산휴가제도는 산모의 건강을 보호해 주기 위한 제도이므로, 출산휴가는 산모의 혼인 여부에 관계없이 허가받을 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-특별휴가-8-8","category":"휴가","number":8,"question":"시보공무원의 출산휴가","answer":"․ 시보공무원도 출산휴가를 허가 받을 수 있음.\n【관련 규정】지방공무원 복무규정 제7조의7(특별휴가)\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-1-1","category":"외부강의 등","number":1,"question":"인사청탁 금품 전달","answer":"․ 부하직원에 대한 인사 청탁과 함께 도지사에게 금품을 전달한 군수의 비위 사실에 대한 파면처분은 적절함.\n【관련 규정】대법원판례 1992. 11. 27. 92누1100\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-2-2","category":"휴가","number":2,"question":"청렴의 의무에 있어 직무의 범위","answer":"․ ‘직무와 관련하여’ 당해 공무원이 직무의 결정권을 갖고 있지 않더라도 그 직무행위와 밀접한 관계가 있는 경우 및 사실상 관리하는 직무행위도 포함됨.\n【관련 규정】대법원판례 1992. 11. 27. 92누 3366\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-3-3","category":"휴가","number":3,"question":"금품수수 비위 해임처분","answer":"․ 시장의 권한에 속하는 농산물도매시장 지정도매인 지정업무를 적정하게 수행하기 위하여 구성된 지정도매인 선정협의회 위원으로 위촉된 시의 실국장이 지정도매인 후보를 선출한 후 금품을 수수한 비위사실에 대한 해임처분은 적절함.\n【관련 규정】대법원판례 1992. 11. 27. 92누3366\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-4-4","category":"휴가","number":4,"question":"세무관리 자문 금품 수수","answer":"․ 회사의 세무 관리에 관한 자문 및 상담에 응하여 오면서 합계 금200만원을 교부받은 세무공무원에 대한 해임처분은 적절함.\n【관련 규정】대법원판례 1993. 12. 28. 93누13698\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-5-5","category":"당직 및 비상근무","number":5,"question":"금품수수 후 반환한 경우","answer":"․ 영득의 의사로 뇌물을 수수한 것이라면 후일 이를 반환하였다 하더라도 뇌물죄의 성립에는 영향이 없음.\n【관련 규정】대법원판례 1983. 3. 22. 83도 113\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-6-6","category":"휴가","number":6,"question":"불법적 이익 제안 대가로 금품요구","answer":"․ 공무원의 청렴의무는 공무원에게 요구되는 가장 기본적인 의무라 할 것인데 적극적으로 상대방에게 금품을 요구하여 그 대가로 직무와 관련된 불법적인 이익을 줄 것을 제안하였다면 돈을 받지 않았다 하더라도 해임처분은 타당함.\n【관련 규정】서울 고판 1994. 10. 20. 94구 1939\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-7-7","category":"휴가","number":7,"question":"공무원의 품위유지의무의 적용범위 및 품위의 의미","answer":"․ 국민으로부터 널리 공무를 수탁하여 국민 전체를 위해 근무하는 공무원의 지위를 고려할 때 공무원의 품위손상행위는 본인은 물론 공직사회에 대한 국민의 신뢰를 실추시킬 우려가 있으므로 공무원에게 직무와 관련된 부분은 물론 사적인 부분에 있어서도 건실한 생활을 할 것을 요구하는품위유지의무를 규정하고 있고, 여기에서품위라 함은 주권자인 국민의 수임자로서의 직책을 맡아 수행해 나가기에 손색이 없는 인품을 말한다.\n【관련 규정】지방공무원법 제55조, 국가공무원법 제63조,\n대법원판례 1998. 2. 27. 97누18172\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-8-8","category":"휴가","number":8,"question":"품위손상에 해당되는 경우","answer":"․ 직장내외의 여러 명으로부터 3억원 이상의 돈을 차용하여 그 채무를 변제하지 못하여 채권자들에게 정신적․물질적 피해를 주었고, 일부 채권자들이 직장을 찾아와서 분위기를 저해하였으며 직장상사 명의의 차용증을 위조하여 돈을 차용한 행위\n․ 뚜렷한 자료 없이 사용자를 수사기관에 고소․고발하거나 그에 대한 인격을 비난하는 내용까지 담긴 진정서 등을 타 기관에 제출하고 공개석상에서 진실과 다른 내용이나 과장된 내용을 가지고 회사를 비방하는 행위\n【관련 규정】대법원판례 1994. 4. 26. 93누22692, 대법원판례 1995. 3. 3. 94누11767\n【관련 부서】총무과"},{"id":"faq-청렴및품위손상-9-9","category":"당직 및 비상근무","number":9,"question":"교원의 품위손상의 의미 및 판단기준","answer":"․ 교원은 항상 사표가 될 품성과 자질의 향상에 힘쓰며 학문의 연찬 및 교육의 원리와 방법을 탐구, 연마하여 학생의 교육에 전심전력하여야 하는 점을 고려할 때\n- 교원에게는 일반 직업인보다 더 높은 도덕성이 요구되고 교원의 품위손상행위는 본인은 물론 교원사회 전체에 대한 국민의 신뢰를 실추시킬 우려가 있으므로 사립학교법은 사립학교 교원에 대하여도 직무와 관련된 부분은 물론 사적인 부분에서도 품위를 유지할 의무를 규정하고 있는데,\n․ 여기서 품위라 함은 국민에 대한 교육자로서의 직책을 맡아 수행해 나가기에 손색이 없는 인품을 말하고 어떤 행위가 품위손상행위에 해당하는가는 구체적 상황에 따라 건전한 사회통념에 의하여 판단하여야 한다.\n【관련 규정】대법원판례 2000. 6. 9. 98두16613\n【관련 부서】교원인사과"},{"id":"faq-영리업무및겸직금지-1-1","category":"휴가","number":1,"question":"자격증의 가족사용","answer":"․ 본인 이외의 타인이 사용할 수 없는 공인중개사 자격증을 가진 공무원이 사무실을 마련하여 가족에게 공인중개업을 운영하게 할 수 없음.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지), 제11조(겸직 허가)\n【관련 부서】총무과"},{"id":"faq-영리업무및겸직금지-2-2","category":"휴가","number":2,"question":"야간 대리운전","answer":"․ 공무원이 퇴근 이후 음주자의 차량을 대리 운전하는 경우에는 동 행위가 심야에 집중됨에 따라 다음날 정상근무에 지장을 초래할 우려가 있으므로 영리업무종사 금지의무에 위반된다고 판단됨.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지), 제11조(겸직 허가)\n【관련 부서】총무과"},{"id":"faq-영리업무및겸직금지-3-3","category":"휴가","number":3,"question":"상가 임대사업","answer":"․ 공무원이 부친의 상가를 상속받아 사업자 등록을 하고 임대사업을 하는 것은 위에서 설명한 영리업무종사 금지 판단기준에 벗어나지 않는다면 가능함.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지), 제11조(겸직 허가)\n【관련 부서】총무과"},{"id":"faq-영리업무및겸직금지-4-4","category":"휴가","number":4,"question":"다단계 판매원 활동 금지","answer":"․ 국가공무원․지방공무원 또는 교육공무원 및 사립학교법에 의한 교원은 다단계 판매원으로 등록을 할 수 없으며, 동법 제55조(벌칙)에 의하면 이를 위반할 시 1년 이하의 징역 또는 3천만원이하의 벌금에 처하도록 규정하고 있음.\n【관련 규정】방문판매 등에 관한 법률 제15조(다단계판매원) 제2항 제1호\n【관련 부서】총무과, 교원인사과"},{"id":"faq-영리업무및겸직금지-5-5","category":"휴가","number":5,"question":"부동산 임대업","answer":"․ 선친으로부터 상속받은 건물을 처분하여 은행융자․세액공제 등을 위하여 세무서에 임대사업자로 등록한 후 다가구주택을 지어 관리인을 두고 임대할 경우\n․ 영리업무금지 규정에 해당되는지의 여부는\n첫째, 국가공무원 복무규정 제25조 제1호 내지 제4호에서 정한 업무에 종사하고 있는가, 둘째, 동 업무에 종사함으로써 공무원의 직무상의 능률의 저해, 공무에 대한 부당한 영향, 국가의 이익과 상반되는 이익의 취득 또는 정부에 대한 불명예스러운 영향을 초래할 우려가 있는가라는 두 가지 요건에 해당되는지를 기준으로 판단하여야 하는 바,\n․ 부동산임대업의 경우 첫째 요건에는 해당되나 사회통념상 부동산 임대업에 소요되는 노력의 정도 등을 감안할 때 둘째 요건에는 해당된다고 보기 어려움.\n․ 다만, 지나치게 과도한 부동산임대로 담당직무 수행에 지장을 초래하거나 관련법령에 저촉되는 부당한 이익을 취득할 경우에는 금지된 영리행위에 해당된다고 볼 수 있음.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지), 제11조(겸직 허가)\n【관련 부서】총무과, 교원인사과"},{"id":"faq-영리업무및겸직금지-6-6","category":"휴가","number":6,"question":"겸직허가 기간 중 소속기관장의 변경","answer":"․ 겸직허가를 받을 때에는 겸직기간을 명시하여 받아야 할 것이며, 허가 받은 기간 내에는 소속기관장이 바뀌어도 별도의 허가를 받을 필요는 없음.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지), 제11조(겸직 허가)\n【관련 부서】총무과"},{"id":"faq-영리업무및겸직금지-7-7","category":"휴가","number":7,"question":"건축사사무소 등록","answer":"․ 건축사 면허를 받은 공무원이 건축사사무소를 개설하여 그 명의로 등록을 필하고 영업행위를 하는 경우 이는 영리업무에 해당됨.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지)\n【관련 부서】총무과"},{"id":"faq-영리업무및겸직금지-8-8","category":"휴가","number":8,"question":"겸직허가의 기준","answer":"․ 공무원의 겸직허가의 판단 기준은 ① 금지대상이 되는 영리업무에 해당되지 않아야 하고 ② 담당직무 수행에 지장이 없어야 하며 ③ 해당 기관이나 단체로부터 정기적인 보수를 받지 않아야 함.\n【관련 규정】지방공무원 복무규정 제10조(영리업무의 금지), 제11조(겸직 허가)\n【관련 부서】총무과"},{"id":"faq-인사혁신처복무관련질의답변-7-1","category":"휴가","number":7,"question":"소속직원의 경조사 관련 출장","answer":"국가공무원 복무징계 관련예규 제6장의 출장에 관하여 문의드립니다\n사례별 출장조치 가능 여부에 보면 소속직원의 경조사에 기관대표의 자격으로 참석하는 약간명의 공무원에 대하여 출장 조치가 가능함 이라고 명시되어 있는데 여기서 \"소속직원의\" 해석에 대하여 문의드립니다.\n․ 「국가공무원 복무·징계관련 예규」에 따라 소속 직원의 경조사에 기관대표의 자격으로 참석하는 약간명에 한하여 출장조치가 가능하며, 이 경우 휴무일, 공휴일인 경우에도 출장조치가 가능합니다. 다만, 해당 소속 부서(장)은 기관대표 자격인지, 개인 친분에 따라 참석하는 것인지 여부 등을 좀 더 면밀하게 파악한 후 출장조치 여부를 결정할 사안임을 알려드립니다.\n․ 문의하신 ‘소속직원 경조사’의 해석에 관해서는 특별휴가규정(국가공무원 복무규정 제20조제1항)에서 유추해 보면 ‘공무원은 본인이 결혼하거나 “그 밖의 경조사”가 있을 경우에는 의 기준에 따른 경조사휴가를 받을 수 있다.’라고 되어 있는 바,\n의 기준에는\n1. 본인 및 자녀의 결혼, 2. 배우자의 출산,\n3. 배우자, 본인 및 배우자의 부모의 사망,\n4. 본인 및 배우자의 조부모‧외조부모의 사망,\n5. 자녀와 그 자녀의 배우자의 사망,\n6. 본인 및 배우자의 형제‧자매의 사망, 7. 본인의 입양 등이 있습니다.\n따라서 소속직원의 경조사는 특별휴가 중 경조사휴가의 의 기준에 준하여 판단하시는 것이 타당하다고 생각됩니다.\n․ 아울러,「국가공무원 복무규정」에 따라 공무원이 출장을 하고자 하는 때에는 근무상황부 또는 근무상황카드에 의하여 사전에 소속기관의 장의 허가를 받아야 합니다. 다만, 불가피한 사유로 사전에 허가를 받지 못한 경우에는 사후에 지체없이 허가를 받아야 합니다.\n【관련 규정】국가공무원 복무·징계관련 예규\n【관련 부서】총무과, 교원인사과\n8"}],"downloads":{"hwpx":"downloads/manual/제4편 복무_251021.hwpx","manual":"downloads/chapter4-manual.pdf"},"meta":{"title":"학교행정업무 길라잡이 웹판","chapter":"제4편 복무","sourceUpdated":"2025-12","contentPolicy":"매뉴얼·FAQ·서식 원문만 표시","officialBoardUrl":"https://www.jbe.go.kr/board/list.jbe?boardId=BBS_0000085&menuCd=DOM_000000106002002000&contentsSid=336","searchExamples":["휴가 개요","연가","병가","공가"]}};
